# For dual-type Pokémon, we need to handle both types
def get_type_effectiveness(move_type, defender_type):
    """Calculate effectiveness multiplier between move type and defender type(s)"""
    # Handle dual-type Pokémon (e.g., "Grass/Poison")
    defender_types = defender_type.split("/") if "/" in defender_type else [defender_type]
    
    multiplier = 1.0
    
    for d_type in defender_types:
        if d_type in type_effectiveness:
            # Check for immunities
            if move_type in type_effectiveness[d_type]["immune_to"]:
                return 0.0  # No effect
            
            # Check for weaknesses
            if move_type in type_effectiveness[d_type]["weak_to"]:
                multiplier *= 2.0
            
            # Check for resistances
            if move_type in type_effectiveness[d_type]["resists"]:
                multiplier *= 0.5
    
    return multiplier

def get_effectiveness_text(multiplier):
    """Get text description for effectiveness"""
    if multiplier == 0.0:
        return "It had no effect!"
    elif multiplier == 0.5:
        return "It's not very effective..."
    elif multiplier == 1.0:
        return ""  # Normal effectiveness, no message needed
    elif multiplier == 2.0:
        return "It's super effective!"
    elif multiplier >= 4.0:
        return "It's very effective!"
    else:
        return ""


