def update_rival_team(player_starter):
        """Update rival's team based on player's starter choice"""
        global trainers
    
        if player_starter == "Bulbasaur":
            rival_starter = "Charmander"  # Fire beats Grass
        elif player_starter == "Charmander":
            rival_starter = "Squirtle"    # Water beats Fire
        elif player_starter == "Squirtle":
            rival_starter = "Bulbasaur"   # Grass beats Water
        else:
            rival_starter = "Charmander"

        rival_pokemon = trainers["rival_gary"]["team"][2]
        rival_pokemon["name"] = rival_starter
        rival_pokemon["moves"] = rival_pokemon["moves_by_species"][rival_starter]

# === POKÉMON CREATION AND STATS FUNCTIONS ===
def calculate_stat(base_stat, level, is_hp=False):
    """Calculate a Pokémon's stat based on base stat and level"""
    if is_hp:
        return (base_stat * 2) + level + 10
    else:
        return int(((base_stat * 2) + level) / 1.5)

def ensure_pokemon_ability(pokemon):
    """Refresh a Pokémon's official ability options while preserving its selection."""
    name = pokemon.get("name")
    ability_options = pokemon_ability_profiles.get(name)
    if ability_options is None:
        raise ValueError(f"No ability profile is defined for Pokémon {name!r}.")

    abilities = [
        {"name": ability_name, "hidden": is_hidden}
        for ability_name, is_hidden in ability_options
    ]
    ability_names = {ability["name"] for ability in abilities}
    selected_ability = pokemon.get("ability")
    if selected_ability not in ability_names:
        selected_ability = next(
            (ability["name"] for ability in abilities if not ability["hidden"]),
            abilities[0]["name"],
        )

    pokemon["abilities"] = abilities
    pokemon["ability"] = selected_ability
    return selected_ability

def create_pokemon(name, level):
    """Create a Pokémon with proper stats and moves based on species and level"""
    pokemon = {
        "name": name,
        "level": level,
        "exp": 0,
        "synergy": 0,
        "synergy_to_next_level": calculate_synergy_to_next_level(level),
        "exp_to_next_level": calculate_exp_to_next_level(level),
        "type": pokemon_types.get(name, "Normal"),
        "moves": [],  # Will be filled with dictionaries
        "known_moves": [],
        "status": "healthy",
        "status_turns": 0,
    }
    ensure_pokemon_ability(pokemon)
    
    # Get base stats for this Pokémon
    if name in pokemon_base_stats:
        base_stats = pokemon_base_stats[name]
        
        # Calculate actual stats
        pokemon["max_hp"] = calculate_stat(base_stats["hp"], level, is_hp=True)
        pokemon["hp"] = pokemon["max_hp"]
        pokemon["attack"] = calculate_stat(base_stats["attack"], level)
        pokemon["defense"] = calculate_stat(base_stats["defense"], level)
        pokemon["sp_attack"] = calculate_stat(base_stats["sp_attack"], level)
        pokemon["sp_defense"] = calculate_stat(base_stats["sp_defense"], level)
        pokemon["speed"] = calculate_stat(base_stats["speed"], level)
    else:
        # Default stats if Pokémon not in database
        pokemon["max_hp"] = 20 + level * 2
        pokemon["hp"] = pokemon["max_hp"]
        pokemon["attack"] = 10 + level
        pokemon["defense"] = 10 + level
        pokemon["sp_attack"] = 10 + level
        pokemon["sp_defense"] = 10 + level
        pokemon["speed"] = 10 + level
    
    # Initialize moves - FIXED: This should include ALL moves up to current level
    initialize_pokemon_moves_with_pp(pokemon)
    
    # Ensure moves are in the correct format
    normalize_pokemon_moves(pokemon)
    
    return pokemon

def initialize_pokemon_moves_with_pp(pokemon):
    """Initialize moves for a Pokémon with PP tracking - FIXED VERSION"""
    name = pokemon["name"]
    level = pokemon["level"]
    
    # Get ALL moves this Pokémon should know up to its current level
    moves_to_know = []
    if name in pokemon_move_learnsets:
        for learn_level in sorted(pokemon_move_learnsets[name].keys()):
            if learn_level <= level:
                # Add all moves learned at this level
                moves_to_know.extend(pokemon_move_learnsets[name][learn_level])
    else:
        # If Pokémon has no defined moveset, give it Tackle
        moves_to_know = ["Tackle"]
    
    # Remove duplicates while preserving order
    unique_moves = []
    for move in moves_to_know:
        if move not in unique_moves:
            unique_moves.append(move)
    
    # Create move list with PP data
    move_list = []
    
    # Start with the most recent 4 moves (most powerful/relevant)
    # If Pokémon knows more than 4 moves, take the last 4
    if len(unique_moves) > 4:
        # Take the most recent 4 moves (assuming higher level moves are better)
        moves_to_use = unique_moves[-4:]
    else:
        moves_to_use = unique_moves
    
    for move_name in moves_to_use:
        if move_name in pokemon_moves:
            move_data = pokemon_moves[move_name]
            move_list.append({
                "name": move_name,
                "pp": move_data["max_pp"],  # Start with full PP
                "max_pp": move_data["max_pp"]
            })

def normalize_pokemon_moves(pokemon):
    """Ensure all Pokémon moves are in dictionary format"""
    if "moves" not in pokemon:
        pokemon["moves"] = []
    
    normalized_moves = []
    for move in pokemon["moves"]:
        if isinstance(move, dict):
            # Already in dictionary format
            normalized_moves.append(move)
        elif isinstance(move, str) and move != "--":
            # Convert string to dictionary
            if move in pokemon_moves:
                move_data = pokemon_moves[move]
                normalized_moves.append({
                    "name": move,
                    "pp": move_data["max_pp"],
                    "max_pp": move_data["max_pp"]
                })
            else:
                # Fallback for undefined moves
                normalized_moves.append({
                    "name": move,
                    "pp": 35,
                    "max_pp": 35
                })
        else:
            # Empty move slot
            normalized_moves.append({"name": "--", "pp": 0, "max_pp": 0})
    
    # Ensure we have exactly 4 move slots
    while len(normalized_moves) < 4:
        normalized_moves.append({"name": "--", "pp": 0, "max_pp": 0})
    
    pokemon["moves"] = normalized_moves

def get_random_wild_pokemon(area):
    """Get a random wild Pokémon with proper stats based on encounter rates"""
    if area not in area_pokemon:
        return None
    
    pokemon_list = area_pokemon[area]
    
    # Generate a random number between 0 and 1
    rand = random.random()
    cumulative_rate = 0
    
    # Select Pokémon based on encounter rates
    for pokemon_data in pokemon_list:
        cumulative_rate += pokemon_data["encounter_rate"]
        if rand <= cumulative_rate:
            name = pokemon_data["name"]
            min_lvl = pokemon_data["min_level"]
            max_lvl = pokemon_data["max_level"]
            level = random.randint(min_lvl, max_lvl)
            
            # Check if this Pokémon has a moveset defined
            if name not in pokemon_move_learnsets:
                print(f"Warning: {name} has no moveset defined! Adding default moves.")
                # Add a default moveset for missing Pokémon
                pokemon_move_learnsets[name] = {
                    1: ["Tackle", "Growl"],
                    5: ["Quick Attack"],
                    10: ["Take Down"]
                }
            
            pokemon = create_pokemon(name, level)
            return pokemon
    
    # Fallback
    fallback_data = pokemon_list[0]
    name = fallback_data["name"]
    min_lvl = fallback_data["min_level"]
    max_lvl = fallback_data["max_level"]
    level = random.randint(min_lvl, max_lvl)
    
    pokemon = create_pokemon(name, level)
    return pokemon

def learn_new_moves(pokemon, new_moves):
    """Handle learning new moves, allowing the player to choose which move to replace"""
    for new_move in new_moves:
        # Get current moves - ensure they're in dictionary format
        current_moves = []
        for move in pokemon.get("moves", []):
            if isinstance(move, dict):
                current_moves.append(move)
            else:
                # Convert string move to dictionary format
                if move != "--" and move in pokemon_moves:
                    move_data = pokemon_moves[move]
                    current_moves.append({
                        "name": move,
                        "pp": move_data["max_pp"],
                        "max_pp": move_data["max_pp"]
                    })
                else:
                    current_moves.append({"name": move, "pp": 0, "max_pp": 0})
        
        # Check for empty slots first
        empty_slots = [i for i, move in enumerate(current_moves) if move["name"] == "--"]
        
        if empty_slots:
            # Fill the first empty slot
            slot_index = empty_slots[0]
            current_moves[slot_index] = {
                "name": new_move,
                "pp": pokemon_moves[new_move]["max_pp"],
                "max_pp": pokemon_moves[new_move]["max_pp"]
            }
        else:
            # No empty slots, let the player choose
            show_move_learning_menu(pokemon, new_move, current_moves)
            
        # Update the moves in the Pokémon
        pokemon["moves"] = current_moves

def show_move_learning_menu(pokemon, new_move, current_moves):
    """Show a menu to choose which move to forget"""
    selected_slot = 0
    viewing = True
    
    # Get move details for the new move
    new_move_data = pokemon_moves.get(new_move, {"type": "Normal", "power": 0, "accuracy": 100, "max_pp": 35})
    
    while viewing:
        window.fill(MENU_BG)
        pygame.draw.rect(window, MENU_BORDER, (15, 5, WIDTH-30, HEIGHT-30), 4)
        
        # Title
        title = font.render(f"{pokemon['name']} wants to learn {new_move}!", True, TITLE_COLOR)
        window.blit(title, (WIDTH//2 - title.get_width()//2, 20))
        
        # New move info
        new_move_info = font.render(f"New Move: {new_move} ({new_move_data['type']})", True, (0, 100, 0))
        window.blit(new_move_info, (WIDTH//2 - new_move_info.get_width()//2, 60))
        
        if new_move_data["power"] > 0:
            power_text = font_small.render(f"Power: {new_move_data['power']} | Acc: {new_move_data['accuracy']}% | PP: {new_move_data['max_pp']}", True, BLACK)
        else:
            power_text = font_small.render(f"Status Move | Acc: {new_move_data['accuracy']}% | PP: {new_move_data['max_pp']}", True, BLACK)
        window.blit(power_text, (WIDTH//2 - power_text.get_width()//2, 85))
        
        # Current moves header
        current_header = font.render(f"But {pokemon['name']} already knows 4 moves!", True, TITLE_COLOR)
        window.blit(current_header, (WIDTH//2 - current_header.get_width()//2, 120))
        
        # Display current moves with details
        for i, move_data in enumerate(current_moves):
            move_name = move_data["name"]
            y_pos = 160 + i * 70
            
            # Highlight selected slot
            if i == selected_slot:
                pygame.draw.rect(window, HIGHLIGHT, (50, y_pos - 5, WIDTH - 100, 60))
                slot_color = WHITE
            else:
                slot_color = BLACK
            
            # Move name and slot number
            slot_text = font.render(f"{i+1}. {move_name}", True, slot_color)
            window.blit(slot_text, (60, y_pos))
            
            # Move details if it's a real move
            if move_name != "--" and move_name in pokemon_moves:
                move_info = pokemon_moves[move_name]
                if move_info["power"] > 0:
                    details = f"Type: {move_info['type']} | Power: {move_info['power']} | Acc: {move_info['accuracy']}% | PP: {move_data['pp']}/{move_data['max_pp']}"
                else:
                    details = f"Type: {move_info['type']} | Status Move | Acc: {move_info['accuracy']}% | PP: {move_data['pp']}/{move_data['max_pp']}"
                
                details_text = font_small.render(details, True, slot_color)
                window.blit(details_text, (60, y_pos + 25))
        
        # Instructions
        instruct_text = font.render("↑↓: Select Move  ENTER: Replace  ESC: Skip Learning", True, BLACK)
        window.blit(instruct_text, (WIDTH//2 - instruct_text.get_width()//2, HEIGHT - 80))
        
        pygame.display.update()
        
        # Handle input
        for event in pygame.event.get():
            if event.type == pygame.QUIT:
                pygame.quit()
                quit()
            
            if event.type == pygame.KEYDOWN:
                if event.key == pygame.K_ESCAPE:
                    # Player chose not to learn the move
                    show_message(f"{pokemon['name']} did not learn {new_move}.")
                    viewing = False
                    return False
                
                elif event.key == pygame.K_DOWN:
                    selected_slot = (selected_slot + 1) % 4
                
                elif event.key == pygame.K_UP:
                    selected_slot = (selected_slot - 1) % 4
                
                elif event.key == pygame.K_RETURN:
                    # Replace the selected move
                    old_move = current_moves[selected_slot]["name"]
                    current_moves[selected_slot] = {
                        "name": new_move,
                        "pp": new_move_data["max_pp"],
                        "max_pp": new_move_data["max_pp"]
                    }
                    
                    show_message(f"{pokemon['name']} forgot {old_move}!")
                    show_message(f"{pokemon['name']} learned {new_move}!")
                    viewing = False
                    return True
    
    return False

def get_forgotten_moves(pokemon):
    """Get moves a Pokémon could have learned but doesn't currently know"""
    pokemon_name = pokemon["name"]
    current_level = pokemon["level"]
    
    # Get current move names
    current_move_names = []
    for move in pokemon["moves"]:
        if isinstance(move, dict):
            current_move_names.append(move["name"])
        else:
            current_move_names.append(move)
    
    # Check if this Pokémon has a learnset
    if pokemon_name not in pokemon_move_learnsets:
        return []
    
    # Find all moves this Pokémon could have learned up to its level
    possible_moves = []
    for learn_level, moves in pokemon_move_learnsets[pokemon_name].items():
        if learn_level <= current_level:
            for move in moves:
                if move not in current_move_names and move not in possible_moves:
                    # Check if it's a valid move that exists in pokemon_moves
                    if move in pokemon_moves:
                        possible_moves.append(move)
    
    # Sort by level learned (approximate)
    # We'll sort them in the order they appear in the learnset
    move_order = {}
    for learn_level, moves in sorted(pokemon_move_learnsets[pokemon_name].items()):
        for move in moves:
            if move in possible_moves:
                move_order[move] = learn_level
    
    # Sort moves by the level they're learned
    possible_moves.sort(key=lambda x: (move_order.get(x, 999), x))
    
    return possible_moves

def open_move_relearner(pokemon=None, team_index=None):
    """
    Move relearner interface where player selects a Pokémon
    and then chooses moves to relearn
    
    Can be called:
    1. Without arguments: Opens Pokémon selection menu
    2. With arguments: Directly opens move selection for specific Pokémon
    """
    
    # If specific Pokémon is provided, go directly to move selection
    if pokemon is not None and team_index is not None:
        open_relearn_moves_menu(pokemon, team_index)
        return
    
    # Otherwise, show Pokémon selection menu
    move_relearner_open = True
    selected_pokemon = 0
    
    while move_relearner_open:
        window.fill((40, 60, 100))  # Dark blue background
        
        # ===== DRAW HEADER =====
        title_font = pygame.font.SysFont("arial", 36, bold=True)
        title = title_font.render("MOVE RELEARNER", True, (255, 255, 200))
        window.blit(title, (WIDTH//2 - title.get_width()//2, 30))
        
        subtitle_font = pygame.font.SysFont("arial", 22)
        subtitle = subtitle_font.render("Select a Pokémon to remember moves", True, (200, 200, 255))
        window.blit(subtitle, (WIDTH//2 - subtitle.get_width()//2, 80))
        
        # ===== DRAW POKÉMON LIST =====
        list_y = 130
        list_height = 300
        
        # Background for Pokémon list
        pygame.draw.rect(window, (30, 40, 70), (50, list_y, WIDTH - 100, list_height), border_radius=10)
        pygame.draw.rect(window, (80, 100, 150), (50, list_y, WIDTH - 100, list_height), 3, border_radius=10)
        
        # Display each Pokémon in the team
        for i, pokemon in enumerate(player_team):
            item_y = list_y + 20 + i * 60
            
            # Highlight selected Pokémon
            if i == selected_pokemon:
                pygame.draw.rect(window, (100, 150, 220), (60, item_y - 5, WIDTH - 120, 50), border_radius=8)
            
            # Pokémon name and level
            poke_font = pygame.font.SysFont("arial", 24)
            poke_text = poke_font.render(f"{pokemon['name']}  Lv. {pokemon['level']}", True, (255, 255, 255))
            window.blit(poke_text, (80, item_y))
            
            # Pokémon type(s)
            type_font = pygame.font.SysFont("arial", 18)
            type_text = type_font.render(f"Type: {pokemon['type']}", True, (200, 200, 150))
            window.blit(type_text, (300, item_y + 5))
            
            # HP bar
            hp_width = 200
            hp_percent = pokemon['hp'] / pokemon['max_hp']
            hp_fill = int(hp_width * hp_percent)
            pygame.draw.rect(window, (100, 100, 100), (500, item_y + 5, hp_width, 20))
            pygame.draw.rect(window, (0, 255, 0) if hp_percent > 0.5 else (255, 200, 0) if hp_percent > 0.2 else (255, 0, 0), 
                           (500, item_y + 5, hp_fill, 20))
            
            hp_text = type_font.render(f"HP: {pokemon['hp']}/{pokemon['max_hp']}", True, (255, 255, 255))
            window.blit(hp_text, (710, item_y + 5))
            
            # Show how many moves can be relearned
            forgotten_moves = get_forgotten_moves(pokemon)
            moves_count = len(forgotten_moves)
            if moves_count > 0:
                count_text = type_font.render(f"{moves_count} moves available", True, (100, 255, 100))
            else:
                count_text = type_font.render("No moves to relearn", True, (200, 200, 200))
            window.blit(count_text, (850, item_y + 5))
        
        # ===== DRAW CONTROLS =====
        controls_y = list_y + list_height + 20
        controls_font = pygame.font.SysFont("arial", 20)
        
        controls = [
            "[↑↓]: Select Pokémon",
            "[ENTER]: Choose Pokémon",
            "[ESC]: Exit"
        ]
        
        for i, control in enumerate(controls):
            control_text = controls_font.render(control, True, (255, 255, 200))
            window.blit(control_text, (100 + i * 300, controls_y))
        
        # Footer note
        note_font = pygame.font.SysFont("arial", 16)
        note_text = note_font.render("Note: Some moves require Heart Scales to relearn (not implemented yet)", True, (255, 200, 200))
        window.blit(note_text, (WIDTH//2 - note_text.get_width()//2, HEIGHT - 40))
        
        pygame.display.flip()
        
        # ===== HANDLE INPUT =====
        for event in pygame.event.get():
            if event.type == pygame.QUIT:
                move_relearner_open = False
                pygame.quit()
                quit()
            
            elif event.type == pygame.KEYDOWN:
                # Exit
                if event.key == pygame.K_ESCAPE:
                    move_relearner_open = False
                
                # Navigation
                elif event.key == pygame.K_DOWN:
                    if selected_pokemon < len(player_team) - 1:
                        selected_pokemon += 1
                elif event.key == pygame.K_UP:
                    if selected_pokemon > 0:
                        selected_pokemon -= 1
                
                # Select Pokémon
                elif event.key == pygame.K_RETURN:
                    if player_team:
                        pokemon = player_team[selected_pokemon]
                        open_relearn_moves_menu(pokemon, selected_pokemon)

def open_relearn_moves_menu(pokemon, team_index):
    """
    Show moves that the selected Pokémon can relearn
    """
    relearn_menu_open = True
    selected_move = 0
    scroll_offset = 0
    moves_per_page = 8
    
    # Get forgotten moves
    forgotten_moves = get_forgotten_moves(pokemon)
    
    if not forgotten_moves:
        show_message(f"{pokemon['name']} has no moves to relearn!")
        return
    
    # Convert to move data
    move_data_list = []
    for move_name in forgotten_moves:
        if move_name in pokemon_moves:
            move_data = pokemon_moves[move_name]
            # Find what level this move is learned at
            learned_at = 1
            if pokemon["name"] in pokemon_move_learnsets:
                for level, moves in pokemon_move_learnsets[pokemon["name"]].items():
                    if move_name in moves:
                        learned_at = level
                        break
            
            move_data_list.append({
                'name': move_name,
                'level': learned_at,
                'type': move_data.get('type', 'Normal'),
                'power': move_data.get('power', 0),
                'accuracy': move_data.get('accuracy', 100),
                'pp': move_data.get('max_pp', 20),
                'max_pp': move_data.get('max_pp', 20)
            })
    
    # Sort by level learned
    move_data_list.sort(key=lambda x: x['level'])
    
    while relearn_menu_open:
        window.fill((40, 60, 100))
        
        # ===== HEADER =====
        title_font = pygame.font.SysFont("arial", 32, bold=True)
        title = title_font.render(f"TEACH MOVES TO {pokemon['name'].upper()}", True, (255, 255, 200))
        window.blit(title, (WIDTH//2 - title.get_width()//2, 30))
        
        subtitle_font = pygame.font.SysFont("arial", 20)
        subtitle = subtitle_font.render(f"Level {pokemon['level']} - {len(move_data_list)} moves available", True, (200, 200, 255))
        window.blit(subtitle, (WIDTH//2 - subtitle.get_width()//2, 70))
        
        # ===== CURRENT MOVES =====
        current_y = 110
        pygame.draw.rect(window, (60, 80, 120), (50, current_y, WIDTH - 100, 80), border_radius=10)
        pygame.draw.rect(window, (100, 120, 180), (50, current_y, WIDTH - 100, 80), 3, border_radius=10)
        
        current_font = pygame.font.SysFont("arial", 24, bold=True)
        current_text = current_font.render("CURRENT MOVES:", True, (255, 255, 200))
        window.blit(current_text, (WIDTH//2 - current_text.get_width()//2, current_y + 10))
        
        # Display current moves
        move_font = pygame.font.SysFont("arial", 18)
        for i in range(4):
            x = 100 + (i % 2) * 400
            y = current_y + 45 + (i // 2) * 25
            
            if i < len(pokemon['moves']):
                move = pokemon['moves'][i]
                move_name = move["name"] if isinstance(move, dict) else move
                move_text = move_font.render(f"{i+1}. {move_name}", True, (255, 255, 255))
            else:
                move_text = move_font.render(f"{i+1}. ---", True, (150, 150, 150))
            
            window.blit(move_text, (x, y))
        
        # ===== AVAILABLE MOVES LIST =====
        list_y = current_y + 100
        list_height = 250
        
        pygame.draw.rect(window, (30, 40, 70), (50, list_y, WIDTH - 100, list_height), border_radius=10)
        pygame.draw.rect(window, (80, 100, 150), (50, list_y, WIDTH - 100, list_height), 3, border_radius=10)
        
        list_title_font = pygame.font.SysFont("arial", 22, bold=True)
        list_title = list_title_font.render("AVAILABLE MOVES:", True, (255, 255, 200))
        window.blit(list_title, (WIDTH//2 - list_title.get_width()//2, list_y + 10))
        
        # Draw visible moves
        visible_moves = move_data_list[scroll_offset:scroll_offset + moves_per_page]
        
        for i, move in enumerate(visible_moves):
            item_y = list_y + 50 + i * 40
            item_index = scroll_offset + i
            
            # Highlight selected move
            if item_index == selected_move:
                pygame.draw.rect(window, (100, 150, 220), (60, item_y - 5, WIDTH - 120, 35), border_radius=5)
            
            # Move name
            move_font = pygame.font.SysFont("arial", 20)
            move_text = move_font.render(move['name'], True, (255, 255, 255))
            window.blit(move_text, (80, item_y))
            
            # Level learned and type
            info_font = pygame.font.SysFont("arial", 16)
            level_text = info_font.render(f"Lv. {move['level']}", True, (200, 200, 100))
            window.blit(level_text, (WIDTH - 150, item_y))
            
            type_text = info_font.render(f"Type: {move['type']}", True, get_type_color(move['type']))
            window.blit(type_text, (WIDTH - 300, item_y))
            
            # Power/PP
            if move['power'] > 0:
                stats_text = info_font.render(f"Power: {move['power']} | PP: {move['pp']}", True, (220, 220, 220))
            else:
                stats_text = info_font.render(f"Status | PP: {move['pp']}", True, (220, 220, 220))
            window.blit(stats_text, (400, item_y))
        
        # Scroll indicator
        if len(move_data_list) > moves_per_page:
            scroll_font = pygame.font.SysFont("arial", 14)
            page_text = f"Page {scroll_offset//moves_per_page + 1}/{(len(move_data_list)-1)//moves_per_page + 1}"
            scroll_text = scroll_font.render(page_text, True, (200, 200, 255))
            window.blit(scroll_text, (WIDTH//2 - scroll_text.get_width()//2, list_y + list_height - 30))
        
        # ===== SELECTED MOVE DETAILS =====
        details_y = list_y + list_height + 10
        selected_move_data = move_data_list[selected_move] if move_data_list else None
        
        if selected_move_data:
            pygame.draw.rect(window, (70, 90, 140), (50, details_y, WIDTH - 100, 80), border_radius=10)
            pygame.draw.rect(window, (120, 140, 190), (50, details_y, WIDTH - 100, 80), 3, border_radius=10)
            
            detail_font = pygame.font.SysFont("arial", 22)
            detail_text = detail_font.render(f"Selected: {selected_move_data['name']}", True, (255, 255, 200))
            window.blit(detail_text, (WIDTH//2 - detail_text.get_width()//2, details_y + 10))
            
            # Full move stats
            stats_font = pygame.font.SysFont("arial", 18)
            if selected_move_data['power'] > 0:
                stats_line = f"Type: {selected_move_data['type']} | Power: {selected_move_data['power']} | Accuracy: {selected_move_data['accuracy']}% | PP: {selected_move_data['pp']}"
            else:
                stats_line = f"Type: {selected_move_data['type']} | Status Move | Accuracy: {selected_move_data['accuracy']}% | PP: {selected_move_data['pp']}"
            
            stats_text = stats_font.render(stats_line, True, (220, 220, 255))
            window.blit(stats_text, (WIDTH//2 - stats_text.get_width()//2, details_y + 45))
        
        # ===== CONTROLS =====
        controls_y = details_y + 90 if selected_move_data else list_y + list_height + 20
        controls_font = pygame.font.SysFont("arial", 18)
        
        controls = [
            "[↑↓]: Select Move",
            "[ENTER]: Teach This Move",
            "[A]: Teach & Replace",
            "[ESC]: Back"
        ]
        
        for i, control in enumerate(controls[:3]):
            control_text = controls_font.render(control, True, (255, 255, 200))
            window.blit(control_text, (100 + i * 350, controls_y))
        
        if len(controls) > 3:
            control_text = controls_font.render(controls[3], True, (255, 255, 200))
            window.blit(control_text, (WIDTH//2 - control_text.get_width()//2, controls_y + 30))
        
        pygame.display.flip()
        
        # ===== HANDLE INPUT =====
        for event in pygame.event.get():
            if event.type == pygame.QUIT:
                relearn_menu_open = False
                pygame.quit()
                quit()
            
            elif event.type == pygame.KEYDOWN:
                # Exit
                if event.key == pygame.K_ESCAPE:
                    relearn_menu_open = False
                
                # Navigation
                elif event.key == pygame.K_UP:
                    if selected_move > 0:
                        selected_move -= 1
                        if selected_move < scroll_offset:
                            scroll_offset = max(0, selected_move)
                elif event.key == pygame.K_DOWN:
                    if selected_move < len(move_data_list) - 1:
                        selected_move += 1
                        if selected_move >= scroll_offset + moves_per_page:
                            scroll_offset = selected_move - moves_per_page + 1
                
                # Teach move (auto-replace first empty slot)
                elif event.key == pygame.K_RETURN:
                    if move_data_list:
                        selected_move_info = move_data_list[selected_move]
                        teach_move_to_pokemon(pokemon, team_index, selected_move_info, auto_replace=True)
                        # Refresh the move list
                        forgotten_moves = get_forgotten_moves(pokemon)
                        # Rebuild move_data_list
                        move_data_list.clear()
                        for move_name in forgotten_moves:
                            if move_name in pokemon_moves:
                                move_data = pokemon_moves[move_name]
                                learned_at = 1
                                if pokemon["name"] in pokemon_move_learnsets:
                                    for level, moves in pokemon_move_learnsets[pokemon["name"]].items():
                                        if move_name in moves:
                                            learned_at = level
                                            break
                                
                                move_data_list.append({
                                    'name': move_name,
                                    'level': learned_at,
                                    'type': move_data.get('type', 'Normal'),
                                    'power': move_data.get('power', 0),
                                    'accuracy': move_data.get('accuracy', 100),
                                    'pp': move_data.get('max_pp', 20),
                                    'max_pp': move_data.get('max_pp', 20)
                                })
                        move_data_list.sort(key=lambda x: x['level'])
                        if selected_move >= len(move_data_list):
                            selected_move = max(0, len(move_data_list) - 1)
                
                # Teach with manual replacement selection
                elif event.key == pygame.K_a:
                    if move_data_list:
                        selected_move_info = move_data_list[selected_move]
                        teach_move_to_pokemon(pokemon, team_index, selected_move_info, auto_replace=False)
                        # Refresh move list
                        forgotten_moves = get_forgotten_moves(pokemon)
                        move_data_list.clear()
                        for move_name in forgotten_moves:
                            if move_name in pokemon_moves:
                                move_data = pokemon_moves[move_name]
                                learned_at = 1
                                if pokemon["name"] in pokemon_move_learnsets:
                                    for level, moves in pokemon_move_learnsets[pokemon["name"]].items():
                                        if move_name in moves:
                                            learned_at = level
                                            break
                                
                                move_data_list.append({
                                    'name': move_name,
                                    'level': learned_at,
                                    'type': move_data.get('type', 'Normal'),
                                    'power': move_data.get('power', 0),
                                    'accuracy': move_data.get('accuracy', 100),
                                    'pp': move_data.get('max_pp', 20),
                                    'max_pp': move_data.get('max_pp', 20)
                                })
                        move_data_list.sort(key=lambda x: x['level'])
                        if selected_move >= len(move_data_list):
                            selected_move = max(0, len(move_data_list) - 1)

def teach_move_to_pokemon(pokemon, team_index, move_data, auto_replace=False):
    """
    Teach a move to a Pokémon, either auto-replacing or asking which move to replace
    """
    move_name = move_data['name']
    
    # Check for empty slots first
    empty_slot = -1
    for i, move in enumerate(pokemon['moves']):
        move_name_current = move["name"] if isinstance(move, dict) else move
        if move_name_current == "--" or move_name_current == "":
            empty_slot = i
            break
    
    if empty_slot >= 0 and auto_replace:
        # Auto-replace empty slot
        pokemon['moves'][empty_slot] = {
            "name": move_name,
            "pp": pokemon_moves[move_name]["max_pp"],
            "max_pp": pokemon_moves[move_name]["max_pp"]
        }
        show_message(f"{pokemon['name']} learned {move_name}!")
        player_team[team_index] = pokemon
        return
    
    elif not auto_replace or empty_slot == -1:
        # Need to replace an existing move
        open_move_replacement_selection(pokemon, team_index, move_data)
    else:
        show_message(f"{pokemon['name']} has no room for new moves!")

def open_move_replacement_selection(pokemon, team_index, move_data):
    """
    Let player choose which move to replace
    """
    replacement_open = True
    selected_slot = 0
    
    while replacement_open:
        window.fill((50, 70, 120))
        
        # Title
        title_font = pygame.font.SysFont("arial", 28, bold=True)
        title = title_font.render(f"REPLACE WHICH MOVE WITH {move_data['name'].upper()}?", True, (255, 255, 200))
        window.blit(title, (WIDTH//2 - title.get_width()//2, 50))
        
        # New move info
        info_font = pygame.font.SysFont("arial", 20)
        if move_data['power'] > 0:
            move_info = f"Type: {move_data['type']} | Power: {move_data['power']} | Acc: {move_data['accuracy']}% | PP: {move_data['pp']}"
        else:
            move_info = f"Type: {move_data['type']} | Status Move | Acc: {move_data['accuracy']}% | PP: {move_data['pp']}"
        
        info_text = info_font.render(move_info, True, (200, 255, 200))
        window.blit(info_text, (WIDTH//2 - info_text.get_width()//2, 90))
        
        # Current moves display
        for i in range(4):
            x = WIDTH//2 - 250 + (i % 2) * 300
            y = 150 + (i // 2) * 100
            
            # Slot background
            slot_color = (80, 100, 160) if i == selected_slot else (60, 80, 140)
            pygame.draw.rect(window, slot_color, (x, y, 250, 80), border_radius=10)
            pygame.draw.rect(window, (100, 120, 180), (x, y, 250, 80), 3, border_radius=10)
            
            # Move name
            slot_font = pygame.font.SysFont("arial", 22)
            if i < len(pokemon['moves']):
                move = pokemon['moves'][i]
                current_move_name = move["name"] if isinstance(move, dict) else move
                slot_text = slot_font.render(f"Slot {i+1}: {current_move_name}", True, (255, 255, 255))
                
                # Show move details if it's a real move
                if current_move_name != "--" and current_move_name in pokemon_moves:
                    details_font = pygame.font.SysFont("arial", 16)
                    current_move_data = pokemon_moves[current_move_name]
                    if current_move_data['power'] > 0:
                        details = f"Power: {current_move_data['power']} | Type: {current_move_data['type']}"
                    else:
                        details = f"Status | Type: {current_move_data['type']}"
                    
                    details_text = details_font.render(details, True, (220, 220, 220))
                    window.blit(details_text, (x + 10, y + 50))
            else:
                slot_text = slot_font.render(f"Slot {i+1}: [Empty]", True, (150, 150, 180))
            
            window.blit(slot_text, (x + 10, y + 15))
        
        # Controls
        controls_font = pygame.font.SysFont("arial", 20)
        controls = [
            "[←→↑↓]: Select Slot",
            "[ENTER]: Replace This Move",
            "[ESC]: Cancel"
        ]
        
        for i, control in enumerate(controls):
            control_text = controls_font.render(control, True, (255, 255, 200))
            window.blit(control_text, (100 + i * 350, 350))
        
        pygame.display.flip()
        
        # Handle input
        for event in pygame.event.get():
            if event.type == pygame.QUIT:
                replacement_open = False
                pygame.quit()
                quit()
            
            elif event.type == pygame.KEYDOWN:
                if event.key == pygame.K_ESCAPE:
                    replacement_open = False
                
                # Navigation
                elif event.key == pygame.K_LEFT:
                    if selected_slot % 2 == 1:
                        selected_slot -= 1
                elif event.key == pygame.K_RIGHT:
                    if selected_slot % 2 == 0 and selected_slot < 3:
                        selected_slot += 1
                elif event.key == pygame.K_UP:
                    if selected_slot >= 2:
                        selected_slot -= 2
                elif event.key == pygame.K_DOWN:
                    if selected_slot <= 1:
                        selected_slot += 2
                
                # Confirm replacement
                elif event.key == pygame.K_RETURN:
                    if selected_slot < len(pokemon['moves']):
                        old_move = pokemon['moves'][selected_slot]
                        old_move_name = old_move["name"] if isinstance(old_move, dict) else old_move
                        
                        # Replace the move
                        pokemon['moves'][selected_slot] = {
                            "name": move_data['name'],
                            "pp": pokemon_moves[move_data['name']]["max_pp"],
                            "max_pp": pokemon_moves[move_data['name']]["max_pp"]
                        }
                        
                        show_message(f"{pokemon['name']} forgot {old_move_name}!")
                        show_message(f"{pokemon['name']} learned {move_data['name']}!")
                        
                        # Update player team
                        player_team[team_index] = pokemon
                    
                    replacement_open = False

def get_type_color(type_name):
    """Get color for Pokémon type (for display)"""
    type_colors = {
        "Normal": (168, 168, 120),
        "Fire": (240, 128, 48),
        "Water": (104, 144, 240),
        "Electric": (248, 208, 48),
        "Grass": (120, 200, 80),
        "Ice": (152, 216, 216),
        "Fighting": (192, 48, 40),
        "Poison": (160, 64, 160),
        "Ground": (224, 192, 104),
        "Flying": (168, 144, 240),
        "Psychic": (248, 88, 136),
        "Bug": (168, 184, 32),
        "Rock": (184, 160, 56),
        "Ghost": (112, 88, 152),
        "Dragon": (112, 56, 248),
        "Dark": (112, 88, 72),
        "Metal": (184, 184, 208),
        "Fairy": (238, 153, 172)
    }
    
    # Handle dual types (take first type)
    if "/" in type_name:
        type_name = type_name.split("/")[0]
    
    return type_colors.get(type_name, (200, 200, 200))

battle_weather = None
battle_terrain = None
battle_turn = 0
battle_last_move = {}
battle_field_effects = {}
battle_weather_suppressed = False
battle_ability_suppressed = False


def get_active_ability(pokemon):
    ability = pokemon.get("ability")
    if ability is None:
        ability = ensure_pokemon_ability(pokemon)
    if battle_ability_suppressed and ability != "Neutralizing Gas":
        return ""
    return ability


def get_active_item(pokemon):
    if get_active_ability(pokemon) == "Klutz":
        return None
    return pokemon.get("held_item")


def apply_stat_stage(pokemon, stat_name, stages, source=None):
    stat_stages = pokemon.setdefault(
        "battle_stat_stages",
        {
            "attack": 0, "defense": 0, "sp_attack": 0, "sp_defense": 0,
            "speed": 0, "accuracy": 0, "evasion": 0,
        },
    )
    if source is not None and stages < 0:
        ability = get_active_ability(pokemon)
        protected_stats = {
            "attack": {"Hyper Cutter"},
            "defense": {"Big Pecks"},
            "accuracy": {"Keen Eye"},
        }
        if ability in {"Clear Body", "White Smoke", "Full Metal Body"} or ability in protected_stats.get(stat_name, set()):
            return False
        if ability == "Mirror Armor":
            apply_stat_stage(source, stat_name, -stages, pokemon)
            return False

    if get_active_ability(pokemon) == "Contrary":
        stages = -stages
    elif get_active_ability(pokemon) == "Simple":
        stages *= 2

    old_stage = stat_stages.get(stat_name, 0)
    stat_stages[stat_name] = max(-6, min(6, old_stage + stages))
    if stat_stages[stat_name] != old_stage and source is not None and stages < 0:
        ability = get_active_ability(pokemon)
        if ability == "Defiant":
            apply_stat_stage(pokemon, "attack", 2)
        elif ability == "Competitive":
            apply_stat_stage(pokemon, "sp_attack", 2)
    return stat_stages[stat_name] != old_stage


def stat_stage_multiplier(pokemon, stat_name):
    stage = pokemon.get("battle_stat_stages", {}).get(stat_name, 0)
    if stage >= 0:
        return (2 + stage) / 2
    return 2 / (2 - stage)


def start_battle_abilities(pokemon, opponent):
    global battle_weather, battle_terrain, battle_weather_suppressed, battle_ability_suppressed
    battle_ability_suppressed = any(
        (active.get("ability") or ensure_pokemon_ability(active)) == "Neutralizing Gas"
        for active in (pokemon, opponent)
    )
    pokemon.setdefault("battle_original_type", pokemon.get("type", "Normal"))
    pokemon.setdefault("battle_stat_stages", {
        "attack": 0, "defense": 0, "sp_attack": 0, "sp_defense": 0,
        "speed": 0, "accuracy": 0, "evasion": 0,
    })
    pokemon.setdefault("battle_turns_active", 0)
    ability = get_active_ability(pokemon)
    if ability == "Neutralizing Gas":
        battle_ability_suppressed = True
    if ability in {"Air Lock", "Cloud Nine"}:
        battle_weather_suppressed = True

    weather_abilities = {
        "Drought": "sun",
        "Desolate Land": "sun",
        "Orichalcum Pulse": "sun",
        "Drizzle": "rain",
        "Primordial Sea": "rain",
        "Sand Stream": "sandstorm",
        "Snow Warning": "snow",
    }
    if ability in weather_abilities:
        battle_weather = weather_abilities[ability]
        show_message(f"{pokemon['name']}'s {ability} made it {battle_weather}!")

    terrain_abilities = {
        "Electric Surge": "Electric",
        "Grassy Surge": "Grassy",
        "Misty Surge": "Misty",
        "Psychic Surge": "Psychic",
    }
    if ability in terrain_abilities:
        battle_terrain = terrain_abilities[ability]
        show_message(f"{pokemon['name']}'s {ability} created {battle_terrain} Terrain!")

    if ability == "Intimidate":
        if get_active_ability(opponent) == "Guard Dog":
            apply_stat_stage(opponent, "attack", 1)
            show_message(f"{opponent['name']}'s Guard Dog raised its Attack!")
        else:
            apply_stat_stage(opponent, "attack", -1, pokemon)
            show_message(f"{pokemon['name']} intimidated {opponent['name']}!")
    elif ability == "Download":
        stat = "attack" if opponent.get("defense", 0) < opponent.get("sp_defense", 0) else "sp_attack"
        apply_stat_stage(pokemon, stat, 1)
        show_message(f"{pokemon['name']}'s Download raised its {stat.replace('_', ' ')}!")
    elif ability == "Dauntless Shield":
        apply_stat_stage(pokemon, "defense", 1)
    elif ability == "Intrepid Sword":
        apply_stat_stage(pokemon, "attack", 1)
    elif ability == "Supersweet Syrup":
        apply_stat_stage(opponent, "evasion", -1, pokemon)

    if ability in {"Anticipation", "Forewarn"}:
        show_message(f"{pokemon['name']} sensed danger from {opponent['name']}!")
    elif ability == "Frisk":
        held_item = opponent.get("held_item")
        if held_item:
            show_message(f"{pokemon['name']} frisked {opponent['name']} and found {held_item}!")


def get_effective_weather():
    if battle_weather_suppressed:
        return None
    return battle_weather


def get_battle_speed(pokemon):
    speed = pokemon.get("speed", 1) * stat_stage_multiplier(pokemon, "speed")
    ability = get_active_ability(pokemon)
    weather = get_effective_weather()
    if ability in {"Chlorophyll", "Orichalcum Pulse"} and weather == "sun":
        speed *= 2
    elif ability in {"Swift Swim"} and weather == "rain":
        speed *= 2
    elif ability in {"Sand Rush"} and weather == "sandstorm":
        speed *= 2
    elif ability in {"Slush Rush"} and weather == "snow":
        speed *= 2
    elif ability == "Surge Surfer" and battle_terrain == "Electric":
        speed *= 2
    elif ability == "Quick Feet" and pokemon.get("status", "healthy") != "healthy":
        speed *= 1.5
    elif pokemon.get("status") == "paralyze":
        speed *= 0.5
    if ability == "Slow Start" and pokemon.get("battle_turns_active", 0) < 5:
        speed *= 0.5
    if get_active_item(pokemon) == "Choice Scarf":
        speed *= 1.5
    return speed


def get_move_category(move_data):
    category = move_data.get("category")
    if category in {"physical", "special"}:
        return category
    special_types = {
        "Fire", "Water", "Grass", "Electric", "Ice", "Psychic", "Dragon", "Dark", "Fairy",
    }
    return "special" if move_data.get("type") in special_types else "physical"


def get_move_accuracy(attacker, defender, move_data):
    accuracy = move_data.get("accuracy", 100)
    accuracy *= stat_stage_multiplier(attacker, "accuracy")
    accuracy /= max(0.01, stat_stage_multiplier(defender, "evasion"))
    attacker_ability = get_active_ability(attacker)
    defender_ability = get_active_ability(defender)

    if attacker_ability == "No Guard" or defender_ability == "No Guard":
        return 100
    if attacker_ability == "Compound Eyes":
        accuracy *= 1.3
    if attacker_ability == "Hustle" and get_move_category(move_data) == "physical":
        accuracy *= 0.8
    if attacker_ability == "Victory Star":
        accuracy *= 1.1
    if defender_ability == "Sand Veil" and battle_weather == "sandstorm":
        accuracy *= 0.8
    if defender_ability == "Snow Cloak" and battle_weather == "snow":
        accuracy *= 0.8
    if defender_ability == "Wonder Skin" and move_data.get("power", 0) == 0:
        accuracy = min(50, accuracy)
    if attacker.get("status") == "confusion" and attacker_ability == "Tangled Feet":
        accuracy *= 0.5
    return min(100, max(1, int(accuracy)))


def get_battle_move_type(attacker, move_data):
    move_type = move_data.get("type", "Normal")
    ability = get_active_ability(attacker)
    if ability == "Normalize":
        return "Normal"

    type_conversions = {
        "Aerilate": "Flying",
        "Galvanize": "Electric",
        "Pixilate": "Fairy",
        "Refrigerate": "Ice",
    }
    if move_data.get("sound-move") and ability == "Liquid Voice":
        return "Water"
    if move_type == "Normal" and ability in type_conversions:
        return type_conversions[ability]
    if ability in {"Protean", "Libero"} and not attacker.get("battle_type_changed"):
        attacker["type"] = move_type
        attacker["battle_type_changed"] = True
        show_message(f"{attacker['name']} changed to the {move_type} type!")
    return move_type


def get_ability_damage_effectiveness(
    attacker,
    defender,
    move_data,
    move_type,
    effectiveness,
    move_name,
    move_power,
    move_has_effect,
    original_move_type,
):
    attacker_ability = get_active_ability(attacker)
    defender_ability = get_active_ability(defender)
    category = get_move_category(move_data)
    damage_modifier = 1.0
    weather = get_effective_weather()
    contact = is_contact_move(move_name, move_data)
    sound_move = bool(move_data.get("sound-move"))

    if attacker_ability in {"Mold Breaker", "Teravolt", "Turboblaze"}:
        defender_ability = ""

    if move_type == "Ground" and defender_ability == "Levitate":
        return 0, 0
    if defender_ability == "Wonder Guard" and effectiveness <= 1:
        return 0, 0

    absorbed_types = {
        "Volt Absorb": "Electric",
        "Lightning Rod": "Electric",
        "Motor Drive": "Electric",
        "Water Absorb": "Water",
        "Storm Drain": "Water",
        "Dry Skin": "Water",
        "Flash Fire": "Fire",
        "Sap Sipper": "Grass",
        "Earth Eater": "Ground",
        "Well-Baked Body": "Fire",
    }
    if absorbed_types.get(defender_ability) == move_type:
        if defender_ability in {"Volt Absorb", "Water Absorb", "Dry Skin"}:
            healed = min(defender["max_hp"] // 4, defender["max_hp"] - defender["hp"])
            defender["hp"] += healed
            if healed:
                show_message(f"{defender['name']}'s {defender_ability} restored HP!")
        elif defender_ability == "Motor Drive":
            apply_stat_stage(defender, "speed", 1)
            show_message(f"{defender['name']}'s Motor Drive raised its Speed!")
        elif defender_ability in {"Lightning Rod", "Storm Drain"}:
            apply_stat_stage(defender, "sp_attack", 1)
            show_message(f"{defender['name']}'s {defender_ability} raised its Sp. Atk!")
        elif defender_ability == "Sap Sipper":
            apply_stat_stage(defender, "attack", 1)
            show_message(f"{defender['name']}'s Sap Sipper raised its Attack!")
        elif defender_ability == "Flash Fire":
            defender["flash_fire_active"] = True
            show_message(f"{defender['name']} absorbed the Fire attack!")
        elif defender_ability == "Earth Eater":
            defender["hp"] = min(defender["max_hp"], defender["hp"] + max(1, defender["max_hp"] // 4))
            show_message(f"{defender['name']}'s Earth Eater restored its HP!")
        elif defender_ability == "Well-Baked Body":
            apply_stat_stage(defender, "defense", 2)
            show_message(f"{defender['name']}'s Well-Baked Body raised its Defense!")
        elif defender_ability == "Wind Rider":
            apply_stat_stage(defender, "attack", 1)
            show_message(f"{defender['name']} rode the wind and raised its Attack!")
        return 0, 0

    if defender_ability == "Thick Fat" and move_type in {"Fire", "Ice"}:
        damage_modifier *= 0.5
    elif defender_ability in {"Heatproof", "Water Bubble"} and move_type == "Fire":
        damage_modifier *= 0.5
    elif defender_ability == "Dry Skin" and move_type == "Fire":
        damage_modifier *= 1.25
    elif defender_ability == "Fluffy" and move_type == "Fire":
        damage_modifier *= 2
    elif defender_ability in {"Filter", "Solid Rock", "Prism Armor"} and effectiveness > 1:
        damage_modifier *= 0.75
    elif defender_ability in {"Multiscale", "Shadow Shield"} and defender["hp"] == defender["max_hp"]:
        damage_modifier *= 0.5
    if defender_ability == "Fluffy" and contact:
        damage_modifier *= 0.5
    if defender_ability == "Fur Coat" and category == "physical":
        damage_modifier *= 0.5
    if defender_ability == "Ice Scales" and category == "special":
        damage_modifier *= 0.5
    if get_active_item(defender) == "Eviolite" and (
        defender.get("can_evolve", defender.get("name") in pokemon_evolutions)
    ):
        damage_modifier *= 2 / 3
    if defender_ability == "Grass Pelt" and battle_terrain == "Grassy":
        damage_modifier *= 0.5
    if defender_ability == "Purifying Salt" and move_type == "Ghost":
        damage_modifier *= 0.5
    if defender_ability == "Punk Rock" and sound_move:
        damage_modifier *= 0.5
    if defender_ability == "Wind Rider" and is_wind_move(move_name, move_data):
        apply_stat_stage(defender, "attack", 1)
        show_message(f"{defender['name']}'s Wind Rider raised its Attack!")
        return 0, 0

    if attacker_ability == "Flash Fire" and attacker.get("flash_fire_active") and move_type == "Fire":
        damage_modifier *= 1.5
    if attacker_ability in {"Blaze", "Overgrow", "Torrent", "Swarm"}:
        boosted_type = {
            "Blaze": "Fire", "Overgrow": "Grass", "Torrent": "Water", "Swarm": "Bug",
        }[attacker_ability]
        if move_type == boosted_type and attacker["hp"] * 3 <= attacker["max_hp"]:
            damage_modifier *= 1.5

    weather_boosts = {
        "sun": {"Fire": 1.5, "Water": 0.5},
        "rain": {"Water": 1.5, "Fire": 0.5},
    }
    damage_modifier *= weather_boosts.get(weather, {}).get(move_type, 1)

    if move_type in attacker.get("type", "Normal").split("/"):
        damage_modifier *= 2 if attacker_ability == "Adaptability" else 1.5

    if category == "physical" and attacker_ability in {"Huge Power", "Pure Power", "Gorilla Tactics"}:
        damage_modifier *= 2 if attacker_ability != "Gorilla Tactics" else 1.5
    if attacker_ability == "Hustle" and category == "physical":
        damage_modifier *= 1.5
    if attacker_ability == "Guts" and category == "physical" and attacker.get("status", "healthy") != "healthy":
        damage_modifier *= 1.5
    if attacker_ability == "Defeatist" and attacker["hp"] * 2 <= attacker["max_hp"]:
        damage_modifier *= 0.5
    if attacker_ability == "Technician" and 0 < move_power <= 60:
        damage_modifier *= 1.5
    if attacker_ability == "Strong Jaw" and move_name in {
        "Bite", "Crunch", "Fire Fang", "Ice Fang", "Thunder Fang", "Poison Fang",
        "Psychic Fangs", "Jaw Lock", "Hyper Fang",
    }:
        damage_modifier *= 1.5
    if attacker_ability == "Sheer Force" and move_has_effect:
        damage_modifier *= 1.3
    if attacker_ability == "Analytic" and get_battle_speed(attacker) < get_battle_speed(defender):
        damage_modifier *= 1.3
    if attacker_ability == "Reckless" and move_data.get("recoil"):
        damage_modifier *= 1.2
    if attacker_ability == "Tough Claws" and contact:
        damage_modifier *= 1.3
    if attacker_ability == "Iron Fist" and is_punching_move(move_name):
        damage_modifier *= 1.2
    if attacker_ability == "Mega Launcher" and is_pulse_move(move_name):
        damage_modifier *= 1.5
    if attacker_ability == "Sharpness" and is_slicing_move(move_name):
        damage_modifier *= 1.5
    if attacker_ability == "Rocky Payload" and move_type == "Rock":
        damage_modifier *= 1.5
    if attacker_ability == "Transistor" and move_type == "Electric":
        damage_modifier *= 1.3
    if attacker_ability == "Dragon's Maw" and move_type == "Dragon":
        damage_modifier *= 1.5
    if attacker_ability == "Solar Power" and weather == "sun":
        damage_modifier *= 1.5
    if attacker_ability == "Flare Boost" and attacker.get("status") == "burn":
        damage_modifier *= 1.5
    if attacker_ability == "Rivalry" and attacker.get("gender") and defender.get("gender"):
        damage_modifier *= 1.25 if attacker["gender"] == defender["gender"] else 0.75
    if get_active_item(attacker) == "Life Orb":
        damage_modifier *= 1.3
    if get_active_item(attacker) == "Choice Band" and category == "physical":
        damage_modifier *= 1.5
    elif get_active_item(attacker) == "Choice Specs" and category == "special":
        damage_modifier *= 1.5
    elif get_active_item(attacker) == "Muscle Band" and category == "physical":
        damage_modifier *= 1.1
    elif get_active_item(attacker) == "Wise Glasses" and category == "special":
        damage_modifier *= 1.1
    if get_active_item(attacker) == "Expert Belt" and effectiveness > 1:
        damage_modifier *= 1.2
    type_items = {
        "Silk Scarf": "Normal", "Poison Barb": "Poison",
        "Charcoal": "Fire", "Mystic Water": "Water", "Miracle Seed": "Grass",
        "Magnet": "Electric", "Never-Melt Ice": "Ice", "Black Belt": "Fighting",
        "Sharp Beak": "Flying", "Twisted Spoon": "Psychic", "Silver Powder": "Bug",
        "Hard Stone": "Rock", "Spell Tag": "Ghost", "Dragon Fang": "Dragon",
        "Black Glasses": "Dark", "Metal Coat": "Metal", "Pixie Plate": "Fairy",
    }
    if type_items.get(get_active_item(attacker)) == move_type:
        damage_modifier *= 1.2
    if attacker_ability == "Toxic Boost" and category == "physical" and attacker.get("status") == "poison":
        damage_modifier *= 1.5
    if attacker_ability == "Water Bubble":
        if move_type == "Water":
            damage_modifier *= 2
    if attacker_ability in {"Sand Force", "Steelworker"} and (
        (attacker_ability == "Sand Force" and weather == "sandstorm"
         and move_type in {"Ground", "Rock", "Steel"})
        or (attacker_ability == "Steelworker" and move_type == "Steel")
    ):
        damage_modifier *= 1.5

    if original_move_type == "Normal" and attacker_ability in {
        "Aerilate", "Galvanize", "Pixilate", "Refrigerate",
    }:
        damage_modifier *= 1.2
    if attacker_ability == "Liquid Voice" and sound_move and move_type == "Water":
        damage_modifier *= 1.2
    if attacker_ability in {"Electromorphosis", "Wind Power"} and attacker.get("charged") and move_type == "Electric":
        damage_modifier *= 2
        attacker["charged"] = False

    if battle_terrain == "Grassy" and move_type == "Grass":
        damage_modifier *= 1.3
    if battle_terrain == "Electric" and move_type == "Electric":
        damage_modifier *= 1.3
    if battle_terrain == "Psychic" and move_type == "Psychic":
        damage_modifier *= 1.3
    if attacker_ability == "Hadron Engine" and battle_terrain == "Electric" and move_type == "Electric":
        damage_modifier *= 1.3
    aura_ability = attacker_ability if attacker_ability in {"Dark Aura", "Fairy Aura"} else defender_ability
    if aura_ability in {"Dark Aura", "Fairy Aura"}:
        aura_type = "Dark" if aura_ability == "Dark Aura" else "Fairy"
        aura_multiplier = 0.75 if (
            get_active_ability(attacker) == "Aura Break"
            or get_active_ability(defender) == "Aura Break"
        ) else 1.33
        if move_type == aura_type:
            damage_modifier *= aura_multiplier
    ruin_defenses = {
        "Tablets of Ruin": "attack",
        "Vessel of Ruin": "sp_attack",
        "Beads of Ruin": "sp_defense",
        "Sword of Ruin": "defense",
    }
    weakened_stat = ruin_defenses.get(defender_ability)
    attack_stat = "attack" if category == "physical" else "sp_attack"
    defense_stat = "defense" if category == "physical" else "sp_defense"
    if weakened_stat == attack_stat:
        damage_modifier *= 0.75
    if attacker_ability == "Sword of Ruin" and category == "physical":
        damage_modifier /= 0.75
    elif attacker_ability == "Beads of Ruin" and category == "special":
        damage_modifier /= 0.75

    return effectiveness, damage_modifier


def is_contact_move(move_name, move_data):
    if "contact" in move_data:
        return move_data["contact"]
    non_contact = {
        "Acid", "Air Cutter", "Air Slash", "Ancient Power", "Aura Sphere",
        "Beam", "Blizzard", "Bubble Beam", "Confusion", "Disarming Voice",
        "Earth Power", "Energy Ball", "Fire Blast", "Flamethrower", "Flash Cannon",
        "Focus Blast", "Giga Drain", "Hyper Beam", "Ice Beam", "Psychic",
        "Shadow Ball", "Sludge Bomb", "Thunder", "Thunderbolt", "Water Pulse",
        "Weather Ball", "Will-O-Wisp", "Zap Cannon",
    }
    return move_name not in non_contact


def is_punching_move(move_name):
    return move_name.endswith("Punch") or move_name in {"Comet Punch", "Mach Punch", "Power-Up Punch"}


def is_pulse_move(move_name):
    return move_name in {
        "Aura Sphere", "Dark Pulse", "Dragon Pulse", "Electro Ball", "Heal Pulse",
        "Origin Pulse", "Water Pulse", "Terrain Pulse",
    }


def is_slicing_move(move_name):
    return move_name in {
        "Aqua Cutter", "Air Cutter", "Bitter Blade", "Ceaseless Edge", "Cross Poison",
        "Cut", "Fury Cutter", "Leaf Blade", "Night Slash", "Psycho Cut",
        "Razor Leaf", "Sacred Sword", "Secret Sword", "Slash", "Solar Blade",
        "Stone Axe", "X-Scissor",
    }


def is_wind_move(move_name, move_data):
    return move_data.get("wind_move", move_name in {
        "Air Cutter", "Air Slash", "Bleakwind Storm", "Fairy Wind", "Gust",
        "Heat Wave", "Hurricane", "Icy Wind", "Razor Wind", "Sandsear Storm",
        "Springtide Storm", "Tailwind", "Twister", "Whirlwind",
    })


def finish_battle_turn(pokemon, opponent):
    ability = get_active_ability(pokemon)
    weather = get_effective_weather()
    pokemon["battle_turns_active"] = pokemon.get("battle_turns_active", 0) + 1
    if ability == "Speed Boost":
        apply_stat_stage(pokemon, "speed", 1)
        show_message(f"{pokemon['name']}'s Speed Boost raised its Speed!")
    elif ability == "Poison Heal" and pokemon.get("status") == "poison":
        healed = min(max(1, pokemon["max_hp"] // 8), pokemon["max_hp"] - pokemon["hp"])
        pokemon["hp"] += healed
        pokemon["status"] = "healthy"
        pokemon["status_turns"] = 0
        show_message(f"{pokemon['name']}'s Poison Heal restored its HP!")

    if ability == "Rain Dish" and weather == "rain":
        pokemon["hp"] = min(pokemon["max_hp"], pokemon["hp"] + max(1, pokemon["max_hp"] // 16))
    elif ability == "Ice Body" and weather == "snow":
        pokemon["hp"] = min(pokemon["max_hp"], pokemon["hp"] + max(1, pokemon["max_hp"] // 16))
    elif ability == "Shed Skin" and pokemon.get("status") != "healthy" and random.random() < 0.3:
        pokemon["status"] = "healthy"
        pokemon["status_turns"] = 0
        show_message(f"{pokemon['name']}'s Shed Skin cured its status!")

    if ability == "Hydration" and get_effective_weather() == "rain" and pokemon.get("status") != "healthy":
        pokemon["status"] = "healthy"
        pokemon["status_turns"] = 0
        show_message(f"{pokemon['name']}'s Hydration cured its status!")
    if ability == "Moody":
        stat_names = ["attack", "defense", "sp_attack", "sp_defense", "speed"]
        raised = random.choice(stat_names)
        lowered = random.choice([stat for stat in stat_names if stat != raised])
        apply_stat_stage(pokemon, raised, 2)
        apply_stat_stage(pokemon, lowered, -1)
        show_message(f"{pokemon['name']}'s Moody changed its stats!")
    if ability == "Harvest" and not pokemon.get("held_item") and pokemon.get("last_berry"):
        if get_effective_weather() == "sun" or random.random() < 0.5:
            pokemon["held_item"] = pokemon.pop("last_berry")
            show_message(f"{pokemon['name']} harvested another berry!")

    if ability == "Dry Skin" and weather == "sun":
        pokemon["hp"] = max(0, pokemon["hp"] - max(1, pokemon["max_hp"] // 8))
    elif ability == "Solar Power" and weather == "sun":
        pokemon["hp"] = max(0, pokemon["hp"] - max(1, pokemon["max_hp"] // 8))

    if weather == "sandstorm":
        pokemon_types = pokemon.get("type", "Normal").split("/")
        if not any(pokemon_type in {"Rock", "Ground", "Metal"} for pokemon_type in pokemon_types):
            if ability not in {"Sand Force", "Sand Rush", "Sand Veil", "Overcoat", "Magic Guard"} and not is_weather_damage_immune(pokemon):
                pokemon["hp"] = max(0, pokemon["hp"] - max(1, pokemon["max_hp"] // 16))
                show_message(f"{pokemon['name']} is buffeted by the sandstorm!")
    if ability == "Bad Dreams" and opponent.get("status") == "sleep":
        opponent["hp"] = max(0, opponent["hp"] - max(1, opponent["max_hp"] // 8))
        show_message(f"{opponent['name']} is tormented by Bad Dreams!")
    if battle_terrain == "Grassy" and is_grounded(pokemon):
        pokemon["hp"] = min(pokemon["max_hp"], pokemon["hp"] + max(1, pokemon["max_hp"] // 16))
    apply_held_item_end_turn(pokemon)


def is_grounded(pokemon):
    if get_active_ability(pokemon) in {"Levitate", "Earth Eater"}:
        return False
    if get_active_item(pokemon) == "Air Balloon":
        return False
    return "Flying" not in pokemon.get("type", "Normal").split("/")


def is_weather_damage_immune(pokemon):
    return (
        get_active_ability(pokemon) in {"Magic Guard", "Overcoat"}
        or get_active_item(pokemon) == "Safety Goggles"
    )


def apply_held_item_end_turn(pokemon):
    held_item = get_active_item(pokemon)
    if not held_item:
        return
    if held_item == "Leftovers":
        heal = max(1, pokemon["max_hp"] // 16)
        pokemon["hp"] = min(pokemon["max_hp"], pokemon["hp"] + heal)
    elif held_item == "Black Sludge":
        if "Poison" in pokemon.get("type", "").split("/"):
            pokemon["hp"] = min(pokemon["max_hp"], pokemon["hp"] + max(1, pokemon["max_hp"] // 16))
        elif get_active_ability(pokemon) != "Magic Guard":
            pokemon["hp"] = max(0, pokemon["hp"] - max(1, pokemon["max_hp"] // 8))


def apply_held_item_status(pokemon, attacker=None):
    held_item = get_active_item(pokemon)
    item_statuses = {
        "Cheri Berry": {"paralyze"},
        "Chesto Berry": {"sleep"},
        "Pecha Berry": {"poison"},
        "Rawst Berry": {"burn"},
        "Aspear Berry": {"freeze"},
        "Persim Berry": {"confusion"},
        "Lum Berry": {"poison", "burn", "paralyze", "sleep", "freeze", "confusion", "infatuation"},
    }
    if (
        held_item in item_statuses
        and pokemon.get("status") in item_statuses[held_item]
        and (attacker is None or get_active_ability(attacker) != "Unnerve")
    ):
        pokemon["held_item"] = None
        pokemon["status"] = "healthy"
        pokemon["status_turns"] = 0
        if get_active_ability(pokemon) == "Cheek Pouch":
            pokemon["hp"] = min(pokemon["max_hp"], pokemon["hp"] + max(1, pokemon["max_hp"] // 3))
        if get_active_ability(pokemon) == "Harvest":
            pokemon["last_berry"] = held_item
        show_message(f"{pokemon['name']}'s {held_item} cured its status!")
        return True
    return False


def apply_move_status_effect(attacker, defender, effect, move_type, chance, move_data=None, move_name=""):
    statuses = {"poison", "burn", "paralyze", "sleep", "freeze", "confusion", "infatuation"}
    if effect not in statuses:
        return False

    move_data = move_data or {}
    status_move = move_data.get("power", 0) == 0
    if not status_move and get_active_ability(attacker) == "Sheer Force":
        return False
    if status_move and get_active_ability(defender) == "Good as Gold" and attacker is not defender:
        show_message(f"{defender['name']}'s Good as Gold blocked the status move!")
        return False
    if random.random() >= chance * (2 if get_active_ability(attacker) == "Serene Grace" else 1):
        return False

    if status_move and get_active_ability(defender) == "Magic Bounce":
        show_message(f"{defender['name']} bounced the status move back!")
        return apply_status_effect(attacker, effect, move_type, attacker)
    return apply_status_effect(defender, effect, move_type, attacker)


def apply_move_stat_effect(attacker, defender, move_data):
    effect = move_data.get("effect")
    effects = effect if isinstance(effect, list) else [effect]
    stat_effects = {
        "raise_attack": (attacker, "attack", 1),
        "increase_attack": (attacker, "attack", 1),
        "lower_attack": (defender, "attack", -1),
        "harshly_lower_attack": (defender, "attack", -2),
        "raise_defense": (attacker, "defense", 1),
        "increase_defense": (attacker, "defense", 1),
        "lower_defense": (defender, "defense", -1),
        "harshly_lower_defense": (defender, "defense", -2),
        "raise_sp_attack": (attacker, "sp_attack", 1),
        "increase_sp_attack": (attacker, "sp_attack", 1),
        "lower_sp_attack": (defender, "sp_attack", -1),
        "harshly_lower_sp_attack": (defender, "sp_attack", -2),
        "raise_sp_defense": (attacker, "sp_defense", 1),
        "increase_sp_defense": (attacker, "sp_defense", 1),
        "lower_sp_defense": (defender, "sp_defense", -1),
        "harshly_lower_sp_defense": (defender, "sp_defense", -2),
        "raise_speed": (attacker, "speed", 1),
        "increase_speed": (attacker, "speed", 1),
        "lower_speed": (defender, "speed", -1),
        "harshly_lower_speed": (defender, "speed", -2),
    }

    combined_effects = {
        "lower_attack_sp_attack": [(defender, "attack", -1), (defender, "sp_attack", -1)],
        "lower_attack_defense": [(defender, "attack", -1), (defender, "defense", -1)],
        "raise_attack_sp_attack": [(attacker, "attack", 1), (attacker, "sp_attack", 1)],
        "raise_attack_defense": [(attacker, "attack", 1), (attacker, "defense", 1)],
        "raise_attack_defense_speed": [
            (attacker, "attack", 1), (attacker, "defense", 1), (attacker, "speed", 1),
        ],
        "lower_defenses": [(defender, "defense", -1), (defender, "sp_defense", -1)],
    }

    for effect_name in effects:
        if effect_name in stat_effects:
            target, stat_name, stages = stat_effects[effect_name]
            apply_stat_stage(target, stat_name, stages, attacker if stages < 0 else None)
        elif effect_name in combined_effects:
            for target, stat_name, stages in combined_effects[effect_name]:
                apply_stat_stage(target, stat_name, stages, attacker if stages < 0 else None)


def apply_battle_move_effect(attacker, defender, move_name, move_data):
    global battle_weather
    effect = move_data.get("effect")
    effects = effect if isinstance(effect, list) else [effect]
    targeted_debuffs = {
        "lower_attack", "harshly_lower_attack", "lower_defense", "harshly_lower_defense",
        "lower_sp_attack", "harshly_lower_sp_attack", "lower_sp_defense",
        "harshly_lower_sp_defense", "lower_speed", "harshly_lower_speed",
        "lower_attack_sp_attack", "lower_attack_defense", "lower_defenses",
    }
    if move_data.get("power", 0) == 0 and attacker is not defender and any(
        effect_name in targeted_debuffs for effect_name in effects
    ):
        defender_ability = get_active_ability(defender)
        if defender_ability == "Good as Gold":
            show_message(f"{defender['name']}'s Good as Gold blocked the status move!")
            return
        if defender_ability == "Magic Bounce":
            show_message(f"{defender['name']} bounced the status move back!")
            attacker, defender = defender, attacker

    weather_moves = {
        "Hail": "snow",
        "Rain Dance": "rain",
        "Sandstorm": "sandstorm",
        "Sunny Day": "sun",
    }
    weather = weather_moves.get(move_name)
    if weather:
        battle_weather = weather
        show_message(f"The weather changed to {weather}!")
    if not (move_data.get("power", 0) > 0 and get_active_ability(attacker) == "Sheer Force"):
        apply_move_stat_effect(attacker, defender, move_data)


def apply_defender_hit_ability(defender, attacker, move_type, previous_hp, damage=0, move_name="", move_data=None):
    ability = get_active_ability(defender)
    if get_active_ability(attacker) in {"Mold Breaker", "Teravolt", "Turboblaze"}:
        ability = ""
    move_data = move_data or {}
    contact = is_contact_move(move_name, move_data)
    if ability == "Stamina":
        apply_stat_stage(defender, "defense", 1)
    elif ability == "Weak Armor":
        apply_stat_stage(defender, "defense", -1, attacker)
        apply_stat_stage(defender, "speed", 2)
    elif ability == "Justified" and move_type == "Dark":
        apply_stat_stage(defender, "attack", 1)
    elif ability == "Rattled" and move_type in {"Dark", "Bug", "Ghost"}:
        apply_stat_stage(defender, "speed", 1)
    elif ability == "Water Compaction" and move_type == "Water":
        apply_stat_stage(defender, "defense", 2)
    elif ability == "Steam Engine" and move_type in {"Fire", "Water"}:
        apply_stat_stage(defender, "speed", 6)
    elif ability == "Anger Shell" and previous_hp * 2 > defender["max_hp"] >= defender["hp"] * 2:
        for stat_name in ("attack", "sp_attack", "speed"):
            apply_stat_stage(defender, stat_name, 1)
        apply_stat_stage(defender, "defense", -1, attacker)
        apply_stat_stage(defender, "sp_defense", -1, attacker)
    elif ability == "Berserk" and previous_hp * 2 > defender["max_hp"] >= defender["hp"] * 2:
        apply_stat_stage(defender, "sp_attack", 1)
    elif ability == "Anger Point" and attacker.get("last_hit_critical"):
        apply_stat_stage(defender, "attack", 6)

    if contact:
        if ability in {"Flame Body", "Static", "Poison Point"}:
            status = {"Flame Body": "burn", "Static": "paralyze", "Poison Point": "poison"}[ability]
            if random.random() < 0.3:
                apply_status_effect(attacker, status, move_type, defender)
        elif ability == "Effect Spore" and random.random() < 0.3:
            apply_status_effect(attacker, random.choice(["poison", "paralyze", "sleep"]), move_type, defender)
        elif ability == "Cute Charm" and random.random() < 0.3:
            apply_status_effect(attacker, "infatuation", move_type, defender)
        elif ability in {"Gooey", "Tangling Hair"}:
            apply_stat_stage(attacker, "speed", -1, defender)
        elif ability in {"Rough Skin", "Iron Barbs"} and get_active_ability(attacker) != "Magic Guard":
            attacker["hp"] = max(0, attacker["hp"] - max(1, attacker["max_hp"] // 8))
            show_message(f"{attacker['name']} was hurt by {ability}!")
        elif ability == "Mummy":
            attacker["ability"] = "Mummy"
            show_message(f"{attacker['name']}'s Ability became Mummy!")
        elif ability == "Lingering Aroma":
            attacker["ability"] = "Lingering Aroma"
            show_message(f"{attacker['name']}'s Ability became Lingering Aroma!")
        elif ability == "Cursed Body" and random.random() < 0.3:
            defender["disabled_move"] = move_name
            show_message(f"{defender['name']}'s Cursed Body disabled {move_name}!")
        elif (
            ability == "Pickpocket"
            and get_active_ability(attacker) != "Sticky Hold"
            and not defender.get("held_item")
            and attacker.get("held_item")
        ):
            defender["held_item"], attacker["held_item"] = attacker["held_item"], None
            show_message(f"{defender['name']} stole {defender['held_item']}!")

        if get_active_item(defender) == "Rocky Helmet" and get_active_ability(attacker) != "Magic Guard":
            attacker["hp"] = max(0, attacker["hp"] - max(1, attacker["max_hp"] // 6))
            show_message(f"{attacker['name']} was hurt by {defender['name']}'s Rocky Helmet!")

    if defender.get("hp", 0) <= 0 and damage > 0:
        if ability == "Aftermath" and contact and get_active_ability(attacker) != "Magic Guard":
            attacker["hp"] = max(0, attacker["hp"] - max(1, attacker["max_hp"] // 4))
        elif ability == "Innards Out":
            attacker["hp"] = max(0, attacker["hp"] - max(1, damage))
        elif ability == "Perish Body" and contact:
            defender["perish_body_target"] = attacker.get("name")

    if ability == "Thermal Exchange" and move_type == "Fire":
        if defender.get("status") == "burn":
            defender["status"] = "healthy"
            defender["status_turns"] = 0
        apply_stat_stage(defender, "attack", 1)
    if ability == "Electromorphosis" or (
        ability == "Wind Power" and is_wind_move(move_name, move_data)
    ):
        defender["charged"] = True


def apply_faint_ability(pokemon):
    ability = get_active_ability(pokemon)
    if ability in {"Moxie", "Chilling Neigh", "Grim Neigh"}:
        stat_name = "attack" if ability != "Grim Neigh" else "sp_attack"
        apply_stat_stage(pokemon, stat_name, 1)
        show_message(f"{pokemon['name']}'s {ability} raised its {stat_name.replace('_', ' ')}!")


def calculate_damage(attacker, defender, move_name, move_data):
    """Calculate damage with all special effects"""
    get_active_ability(attacker)
    get_active_ability(defender)
    attacker["last_hit_critical"] = False
    original_move_type = move_data.get("type", "Normal")
    move_type = get_battle_move_type(attacker, move_data)

    if get_active_ability(defender) == "Soundproof" and (move_data.get("sound-move") or move_name in {
        "Boomburst", "Bug Buzz", "Chatter", "Clanging Scales", "Clangorous Soul",
        "Disarming Voice", "Echoed Voice", "Grass Whistle", "Growl", "Heal Bell",
        "Hyper Voice", "Metal Sound", "Noble Roar", "Perish Song", "Roar",
        "Round", "Screech", "Sing", "Snarl", "Snore", "Sparkling Aria",
        "Supersonic", "Uproar",
    }):
        if get_active_ability(attacker) not in {"Mold Breaker", "Teravolt", "Turboblaze"}:
            return 0, 0
    if get_active_ability(defender) == "Bulletproof" and move_name in {
        "Aura Sphere", "Bullet Seed", "Electro Ball", "Energy Ball", "Focus Blast",
        "Gyro Ball", "Ice Ball", "Magnet Bomb", "Mud Bomb", "Octazooka",
        "Pollen Puff", "Rock Wrecker", "Shadow Ball", "Sludge Bomb", "Weather Ball",
        "Zap Cannon",
    }:
        if get_active_ability(attacker) not in {"Mold Breaker", "Teravolt", "Turboblaze"}:
            return 0, 0

    defender_type = defender.get("type", "Normal")
    effectiveness = get_type_effectiveness(move_type, defender_type)
    if (
        effectiveness == 0
        and get_active_ability(attacker) == "Scrappy"
        and move_type in {"Normal", "Fighting"}
        and "Ghost" in defender_type.split("/")
    ):
        remaining_types = [
            defender_part for defender_part in defender_type.split("/")
            if defender_part != "Ghost"
        ]
        effectiveness = get_type_effectiveness(move_type, "/".join(remaining_types)) if remaining_types else 1
    if (
        move_data.get("priority", 0) > 0
        and get_active_ability(defender) in {"Armor Tail", "Dazzling", "Queenly Majesty"}
    ):
        return 0, 0
    if (
        move_data.get("priority", 0) > 0
        and battle_terrain == "Psychic"
        and is_grounded(defender)
    ):
        return 0, 0
    effectiveness, damage_modifier = get_ability_damage_effectiveness(
        attacker,
        defender,
        move_data,
        move_type,
        effectiveness,
        move_name,
        move_data.get("power", 0),
        "effect" in move_data,
        original_move_type,
    )

    damage = None
    if "fixed_damage" in move_data:
        if effectiveness == 0:
            return 0, effectiveness
        if move_data["fixed_damage"] == "half_hp":
            damage = defender["hp"] // 2
            if damage < 1:
                damage = 1
        elif isinstance(move_data["fixed_damage"], int):
            damage = move_data["fixed_damage"]

    if damage is None:
        level = attacker["level"]
        power = move_data["power"]
        category = get_move_category(move_data)
        attack_stat = "attack" if category == "physical" else "sp_attack"
        defense_stat = "defense" if category == "physical" else "sp_defense"
        attack = attacker.get(attack_stat, attacker.get("attack", 1))
        defense = defender.get(defense_stat, defender.get("defense", 1))
        attack *= stat_stage_multiplier(attacker, attack_stat)
        defense *= stat_stage_multiplier(defender, defense_stat)
        if category == "physical" and attacker.get("status") == "burn" and get_active_ability(attacker) != "Guts":
            attack *= 0.5
        if get_active_ability(defender) == "Unaware":
            attack = attacker.get(attack_stat, attacker.get("attack", 1))
        if get_active_ability(attacker) == "Unaware":
            defense = defender.get(defense_stat, defender.get("defense", 1))
        if get_active_ability(attacker) == "Slow Start" and attacker.get("battle_turns_active", 0) < 5 and category == "physical":
            attack *= 0.5
        if get_active_ability(defender) == "Flower Gift" and get_effective_weather() == "sun":
            defense *= 1.5
        if get_active_ability(defender) == "Marvel Scale" and defender.get("status", "healthy") != "healthy" and category == "physical":
            defense *= 1.5
        if get_active_item(attacker) == "Deep Sea Tooth" and attacker.get("name") == "Clamperl" and category == "special":
            attack *= 2
        if get_active_item(defender) == "Deep Sea Scale" and defender.get("name") == "Clamperl" and category == "special":
            defense *= 2
        if get_active_item(attacker) == "Light Ball" and attacker.get("name") == "Pikachu":
            attack *= 2

        base_damage = (level * power * attack) // (defense * 3)
        damage = int((base_damage + 10) * effectiveness * damage_modifier * random.uniform(0.85, 1.0))

        critical_chance = 0.0625
        if move_data.get("high_crit") or move_data.get("effect") == "high_crit":
            critical_chance += 0.0625
        if get_active_ability(attacker) == "Super Luck":
            critical_chance += 0.0625
        if get_active_item(attacker) == "Scope Lens":
            critical_chance += 0.0625
        critical = move_data.get("always_crit", False) or random.random() < min(0.5, critical_chance)
        attacker["last_hit_critical"] = critical

        if damage < 1 and effectiveness > 0:
            damage = 1

        multi_hit_key = "multi_hit" if "multi_hit" in move_data else "multi-hit" if "multi-hit" in move_data else None
        if multi_hit_key:
            hits = 1
            hit_spec = move_data[multi_hit_key]
            if get_active_ability(attacker) == "Skill Link":
                hits = 5
            elif isinstance(hit_spec, tuple):
                hits = random.randint(hit_spec[0], hit_spec[1])
            elif isinstance(hit_spec, bool):
                hits = random.randint(2, 5) if hit_spec else 1
            else:
                hits = hit_spec

            total_damage = 0
            for _ in range(hits):
                hit_damage = int(
                    (base_damage + 10) * effectiveness * damage_modifier * random.uniform(0.85, 1.0)
                )
                if hit_damage < 1 and effectiveness > 0:
                    hit_damage = 1
                total_damage += hit_damage

            damage = total_damage
            show_message(f"Hit {hits} time(s)!")

        if critical and get_active_ability(defender) not in {"Battle Armor", "Shell Armor"}:
            critical_multiplier = 2.25 if get_active_ability(attacker) == "Sniper" else 1.5
            damage = int(damage * critical_multiplier)
            show_message("A critical hit!")

    if (get_active_ability(defender) == "Sturdy"
            and defender["hp"] == defender["max_hp"]
            and "multi_hit" not in move_data
            and "multi-hit" not in move_data
            and damage >= defender["hp"]):
        damage = defender["hp"] - 1
        show_message(f"{defender['name']} endured the hit with Sturdy!")

    held_item = defender.get("held_item")
    if damage >= defender.get("hp", 0) and defender.get("hp", 0) == defender.get("max_hp"):
        if held_item == "Focus Sash" or (
            held_item == "Focus Band" and random.random() < 0.1
        ):
            damage = defender["hp"] - 1
            defender["held_item"] = None
            show_message(f"{defender['name']} hung on with {held_item}!")
    if held_item == "Air Balloon" and move_type == "Ground":
        damage = 0
        effectiveness = 0
        show_message(f"{defender['name']} floated up with its Air Balloon!")
    
    return damage, effectiveness


def apply_held_item_after_damage(pokemon, damage, move_type, attacker=None):
    if damage <= 0:
        return
    held_item = pokemon.get("held_item")
    if held_item == "Air Balloon" and move_type != "Ground":
        pokemon["held_item"] = None
        show_message(f"{pokemon['name']}'s Air Balloon popped!")
        return
    if (
        held_item in {"Oran Berry", "Sitrus Berry"}
        and pokemon["hp"] > 0
        and pokemon["hp"] * 2 <= pokemon["max_hp"]
        and (attacker is None or get_active_ability(attacker) != "Unnerve")
    ):
        heal = 10 if held_item == "Oran Berry" else max(1, pokemon["max_hp"] // 4)
        if get_active_ability(pokemon) == "Ripen":
            heal *= 2
        pokemon["hp"] = min(pokemon["max_hp"], pokemon["hp"] + heal)
        if get_active_ability(pokemon) == "Cheek Pouch":
            pokemon["hp"] = min(pokemon["max_hp"], pokemon["hp"] + max(1, pokemon["max_hp"] // 3))
        pokemon["held_item"] = None
        if held_item.endswith("Berry") and get_active_ability(pokemon) == "Harvest":
            pokemon["last_berry"] = held_item
        show_message(f"{pokemon['name']} ate its {held_item} and restored HP!")


def apply_attacking_held_item(pokemon, defender, move_data, damage):
    if damage <= 0:
        return
    held_item = pokemon.get("held_item")
    if held_item == "Life Orb" and not (
        get_active_ability(pokemon) == "Sheer Force" and move_data.get("effect")
    ):
        recoil = max(1, pokemon["max_hp"] // 10)
        if get_active_ability(pokemon) != "Magic Guard":
            pokemon["hp"] = max(0, pokemon["hp"] - recoil)
            show_message(f"{pokemon['name']} was hurt by its Life Orb!")
    elif held_item == "Shell Bell":
        heal = max(1, damage // 8)
        pokemon["hp"] = min(pokemon["max_hp"], pokemon["hp"] + heal)
        show_message(f"{pokemon['name']}'s Shell Bell restored HP!")
    if get_active_ability(pokemon) == "Sheer Force" and move_data.get("effect"):
        return
    if held_item == "King's Rock" and random.random() < 0.1:
        defender["battle_flinched"] = True

def update_game_time(minutes_to_add=10):
    """
    Update the game time by adding minutes
    Call this when player moves, battles, etc.
    """
    global game_time, game_day
    
    # Add time
    game_time += minutes_to_add / 60 * time_speed
    
    # Check if day passed
    if game_time >= 24:
        game_time -= 24
        game_day += 1
        # Trigger daily events
        trigger_daily_events()
    
    return game_time, game_day

def trigger_daily_events():
    """Things that happen every new day"""
    global berry_plots
    
    # Update berry growth
    berry_plots = update_berry_growth(berry_plots, game_day)
    
    # You can add more daily events here:
    # - Pokémon happiness decay
    # - Berry tree regrowth
    # - Shop restocks
    # - etc.

def quick_sleep():
    """Skip time to next morning"""
    global game_time, game_day
    
    if game_time < 6:
        # Still nighttime, sleep until morning
        hours_to_sleep = 6 - game_time
        game_time = 6
        show_message(f"You slept for {hours_to_sleep:.1f} hours...")
    else:
        # It's daytime, sleep until next morning
        hours_to_sleep = (24 - game_time) + 6
        game_time = 6
        game_day += 1  # Next day
    
    # Update berries (if you have them)
    if 'berry_plots' in globals():
        update_berry_growth(berry_plots, game_day)
    
    # Play a sound if you have one
    try:
        pygame.mixer.Sound.play(pygame.mixer.Sound('sounds/sleep.wav'))
    except:
        pass

def open_pc_storage(boxes, current_team):
    """
    Pokémon-style PC interface with proper graphics - 54 SLOTS VERSION
    """
    pc_open = True
    current_box = 0
    cursor_pos = 0  # 0-5 party, 6+ box
    mode = "party"  # "party" or "box"
    
    # Window dimensions
    WINDOW_WIDTH = 1050
    WINDOW_HEIGHT = 560
    
    # Box configuration - 54 slots: 9 columns × 6 rows
    BOX_CAPACITY = 54
    BOX_COLS = 9       # Number of columns
    BOX_ROWS = 6       # Number of rows
    
    # Colors matching Pokémon style
    PC_BG = (40, 40, 100)  # Dark blue background
    PC_WINDOW = (220, 230, 255)  # Light blue window
    PC_TEXT = (50, 50, 100)  # Dark blue text
    PC_HIGHLIGHT = (255, 240, 100)  # Yellow highlight
    PC_BORDER = (100, 100, 180)  # Medium blue border
    
    while pc_open:
        # Clear with PC blue
        window.fill(PC_BG)
        
        # ===== DRAW MAIN PC WINDOW =====
