        pygame.draw.rect(window, (255, 255, 255), (35, 35, 980, 50), border_radius=3)
        
        # PC Title
        title_font = pygame.font.SysFont("arial", 32, bold=True)
        title_text = title_font.render("POKéMON STORAGE SYSTEM", True, PC_TEXT)
        window.blit(title_text, (525 - title_text.get_width()//2, 55))
        
        # Box number display
        box_font = pygame.font.SysFont("arial", 24, bold=True)
        box_text = box_font.render(f"BOX {current_box + 1}", True, (200, 50, 50))
        window.blit(box_text, (1000 - box_text.get_width(), 60))
        
        # ===== DRAW PARTY SECTION =====
