game_folder = os.path.dirname(__file__)
assets_folder = os.path.join(game_folder, "assets")

def show_quick_message(text, duration=1000):
    """Show a quick message that disappears after a duration"""
    # Fill the screen with white
    window.fill(WHITE)
    
    # Draw the message
    message = font.render(text, True, BLACK)
    window.blit(message, (WIDTH//2 - message.get_width()//2, HEIGHT//2))
    pygame.display.update()
    
    # Wait for the duration, but still process events
    start_time = pygame.time.get_ticks()
    while pygame.time.get_ticks() - start_time < duration:
        for event in pygame.event.get():
            if event.type == pygame.QUIT:
                pygame.quit()
                quit()
            if event.type == pygame.KEYDOWN:
                if event.key == pygame.K_ESCAPE:
                    return  # Skip remaining time if ESC pressed
        pygame.time.delay(10)  # Small delay to prevent CPU overuse

def get_asset_path(filename):
    """Get the full path to an asset file in assets folder"""
    base_folder = os.path.dirname(os.path.abspath(__file__))
    assets_folder = os.path.join(base_folder, "assets")
    return os.path.join(assets_folder, filename)

def get_trainer_sprite_path(filename):
    """Get the full path to a trainer sprite file"""
    base_folder = os.path.dirname(os.path.abspath(__file__))
    trainer_sprites_folder = os.path.join(base_folder, "trainer_sprites")
    return find_sprite_path(os.path.join(trainer_sprites_folder, filename))

def get_back_sprite_path(filename):
    """Get the full path to a back sprite file"""
    base_folder = os.path.dirname(os.path.abspath(__file__))
    back_sprites_folder = os.path.join(base_folder, "back_sprites")
    return find_sprite_path(os.path.join(back_sprites_folder, filename))

def get_front_sprite_path(filename):
    """Get the full path to a front sprite file"""
    base_folder = os.path.dirname(os.path.abspath(__file__))
    front_sprites_folder = os.path.join(base_folder, "front_sprites")
    return find_sprite_path(os.path.join(front_sprites_folder, filename))

def sprite_path_candidates(path):
    """Return PNG and GIF versions of a sprite path, preferring PNG."""
    base, extension = os.path.splitext(path)
    if extension.lower() in (".png", ".gif"):
        return [base + ".png", base + ".gif"]
    return [path + ".png", path + ".gif"]

def find_sprite_path(path):
    """Find a sprite using its PNG path first, then its GIF equivalent."""
    for candidate in sprite_path_candidates(path):
        if os.path.exists(candidate):
            return candidate
    return path

def load_sprite_image(path, size=None, fit_size=None):
    """Load a PNG or animated GIF sprite into a mutable Pygame surface."""
    def prepare_frame(frame):
        if fit_size:
            scale = min(fit_size[0] / frame.get_width(), fit_size[1] / frame.get_height())
            frame_size = (max(1, int(frame.get_width() * scale)),
                          max(1, int(frame.get_height() * scale)))
            return pygame.transform.scale(frame, frame_size)
        if size:
            return pygame.transform.scale(frame, size)
        return frame

    if os.path.splitext(path)[1].lower() != ".gif":
        image = pygame.image.load(path).convert_alpha()
        return prepare_frame(image)

    try:
        from PIL import Image, ImageSequence
    except ImportError as error:
        print("Cannot load animated GIF sprite; install Pillow with 'pip install Pillow'.")
        raise RuntimeError(
            "Animated GIF sprites require Pillow. Install it with 'pip install Pillow'."
        ) from error

    cache_key = (os.path.abspath(path), size, fit_size)
    if cache_key in animated_sprite_cache:
        return animated_sprite_cache[cache_key]

    frames = []
    durations = []
    with Image.open(path) as gif:
        for frame in ImageSequence.Iterator(gif):
            rgba = frame.convert("RGBA")
            surface = pygame.image.fromstring(rgba.tobytes(), rgba.size, "RGBA").convert_alpha()
            frames.append(prepare_frame(surface))
            durations.append(max(10, frame.info.get("duration", 100)))

    if not frames:
        raise ValueError(f"GIF contains no frames: {path}")

    sprite = frames[0].copy()
    if len(frames) > 1:
        animation = {
            "surface": sprite,
            "frames": frames,
            "durations": durations,
            "frame_index": 0,
            "elapsed": 0,
            "last_update": pygame.time.get_ticks(),
        }
        sprite_animations.append(animation)
    animated_sprite_cache[cache_key] = sprite
    return sprite

def advance_sprite_animations():
    """Advance registered GIF sprites without replacing their shared surfaces."""
    now = pygame.time.get_ticks()
    for animation in sprite_animations:
        animation["elapsed"] += now - animation["last_update"]
        animation["last_update"] = now
        while animation["elapsed"] >= animation["durations"][animation["frame_index"]]:
            animation["elapsed"] -= animation["durations"][animation["frame_index"]]
            animation["frame_index"] = (animation["frame_index"] + 1) % len(animation["frames"])
            surface = animation["surface"]
            surface.fill((0, 0, 0, 0))
            surface.blit(animation["frames"][animation["frame_index"]], (0, 0))

def get_music_path(filename):
    """Get the full path to a music file"""
    base_folder = os.path.dirname(os.path.abspath(__file__))
    music_folder = os.path.join(base_folder, "music")
    return os.path.join(music_folder, filename)

