def load_trainer_sprite(sprite_name):
    """Load trainer sprite"""
    path = get_trainer_sprite_path(f"{sprite_name}.png")
    
    if os.path.exists(path):
        try:
            return load_sprite_image(path, size=(TILE_SIZE, TILE_SIZE))
        except Exception as e:
            print(f"DEBUG: Error loading {sprite_name}.png: {e}")
            # Fall through to fallback sprite
    
    # Create fallback sprites
    surf = pygame.Surface((TILE_SIZE, TILE_SIZE), pygame.SRCALPHA)
    
    return surf

def create_fallback_trainer_sprite(trainer_type):
    """Create a simple colored sprite for trainers if image files are missing"""
    surf = pygame.Surface((TILE_SIZE, TILE_SIZE), pygame.SRCALPHA)
    
    if trainer_type == "gym_leader":
        # Purple for gym leader
        surf.fill((100, 50, 150, 255))
        pygame.draw.rect(surf, (200, 150, 255), (0, 0, TILE_SIZE, TILE_SIZE), 3)
        # Draw a simple crown
        pygame.draw.polygon(surf, (255, 215, 0), 
                          [(TILE_SIZE//2-10, TILE_SIZE//3),
                           (TILE_SIZE//2, TILE_SIZE//6),
                           (TILE_SIZE//2+10, TILE_SIZE//3)])
    elif "dark" in trainer_type.lower():
        # Dark purple for dark trainers
        surf.fill((60, 0, 100, 255))
        pygame.draw.rect(surf, (150, 50, 200), (0, 0, TILE_SIZE, TILE_SIZE), 2)
    else:
        # Brown for regular trainers
        surf.fill((150, 100, 50, 255))
        pygame.draw.rect(surf, (100, 50, 0), (0, 0, TILE_SIZE, TILE_SIZE), 2)
    
    return surf

def show_trainer_dialogue(trainer, dialogue_type):
    """Show trainer dialogue before/after battle (safe access)."""
    dialogue = trainer.get("dialogue", {})
    if dialogue_type == "start":
        text = dialogue.get("start", "")
    elif dialogue_type == "win":
        text = dialogue.get("win", "")
    else:
        text = dialogue.get("lose", "")
    name = trainer.get("name", "Trainer")
    if text:
        show_message(f"{name}: {text}")

def create_trainer_pokemon(pokemon_data):
    """Create a trainer Pokémon, using its configured moves when provided."""
    name = pokemon_data["name"]
    level = pokemon_data["level"]
    pokemon = create_pokemon(name, level)
    
    # Ensure Pokémon has proper moves
    initialize_pokemon_moves_with_pp(pokemon)

    custom_moves = pokemon_data.get("moves")
    if custom_moves is not None:
        if not isinstance(custom_moves, list) or not 1 <= len(custom_moves) <= 4:
            raise ValueError(
                f"{name} trainer moves must be a list of one to four move names"
            )
        invalid_moves = [
            move for move in custom_moves
            if not isinstance(move, str) or move not in pokemon_moves
        ]
        if invalid_moves:
            raise ValueError(
                f"{name} trainer moves are not defined in pokemon_moves: "
                f"{invalid_moves}"
            )
        pokemon["moves"] = custom_moves.copy()
        normalize_pokemon_moves(pokemon)
    
    return pokemon

def battle_trainer(trainer):
    """Battle each Pokémon on a trainer's team."""
    global game_state
    
    trainer_name = trainer.get("name", "Trainer")
    trainer_team = trainer.get("team", [])
    if not trainer_team:
        game_state = "play"
        return "player_lost"

    if not any(pokemon.get("hp", 0) > 0 for pokemon in player_team):
        show_message("You have no Pokémon able to battle!")
        show_trainer_dialogue(trainer, "lose")
        game_state = "play"
        return "player_lost"

    for pokemon_data in trainer_team:
        opponent_pokemon = create_trainer_pokemon(pokemon_data)
        result = battle(
            opponent_pokemon,
            is_trainer_battle=True,
            trainer_name=trainer_name,
        )
        if result != "player_won":
            show_trainer_dialogue(trainer, "lose")
            game_state = "play"
            return "player_won" if result == "player_won" else "player_lost"

    show_trainer_dialogue(trainer, "win")
    reward = trainer.get("reward_money", 0)
    if reward:
        items["money"] = items.get("money", 0) + reward
        show_message(f"You received ${reward}!")

    game_state = "play"

    return "player_won"

