def show_wake_up_intro():
    """Show wake up sequence - SIMPLE NO-BLOCKING VERSION"""
    global intro_complete, game_state, player_row, player_col, current_map
    
    # Skip all complex dialogue - just show one simple message
    window.fill(WHITE)
    
    # Show mom's message
    message_lines = [
        "Mom: Good morning! Professor Gale is waiting.",
        "He wants you to choose your first Pokémon.",
        "",
        "You received: Potion x1, Poké Ball x5",
        "",
        "Press any key to continue..."
    ]
    
    # Draw all lines
    for i, line in enumerate(message_lines):
        text = font.render(line, True, BLACK)
        window.blit(text, (WIDTH//2 - text.get_width()//2, HEIGHT//2 - 100 + i * 40))
    
    pygame.display.update()
    
    # Wait for ANY key press
    waiting = True
    while waiting:
        for event in pygame.event.get():
            if event.type == pygame.QUIT:
                pygame.quit()
                quit()
            if event.type == pygame.KEYDOWN:
                waiting = False
            if event.type == pygame.MOUSEBUTTONDOWN:
                waiting = False
        pygame.time.delay(10)
    
    # Add items
    items["Potion"] = 1
    items["Poké Ball"] = 5
    
    # Set player position in the BEDROOM
    current_map = "player_bedroom"
    player_row, player_col = 4, 5
    
    # Mark as complete
    intro_complete = True
    game_state = "play"
    
    # Force a redraw
    return

