def load_grass_texture():
    """Load grass texture from grass.png"""
    assets_folder = os.path.join(game_folder, "assets")
    grass_path = os.path.join(assets_folder, "grass.png")
    if os.path.exists(grass_path):
        try:
            texture = pygame.image.load(grass_path).convert_alpha()
            return pygame.transform.scale(texture, (TILE_SIZE, TILE_SIZE))
        except:
            pass
    
    # Create simple grass texture
    surf = pygame.Surface((TILE_SIZE, TILE_SIZE))
    for x in range(TILE_SIZE):
        for y in range(TILE_SIZE):
            if (x // 8 + y // 8) % 2 == 0:
                color = (100, 200, 100)
            else:
                color = (80, 180, 80)
            surf.set_at((x, y), color)
    return surf

