def load_water_texture():
    """Load water texture from water.png"""
    water_path = get_asset_path("water.png")

    if os.path.exists(water_path):
        try:
            texture = pygame.image.load(water_path).convert_alpha()
            return pygame.transform.scale(texture, (TILE_SIZE, TILE_SIZE))
        except:
            pass
    
    # Create simple water texture
    surf = pygame.Surface((TILE_SIZE, TILE_SIZE))
    for x in range(TILE_SIZE):
        for y in range(TILE_SIZE):
            wave = int(10 * ((x + y) % 3))
            color = (
                max(0, min(255, 0 + wave)),
                max(0, min(255, 0 + wave)),
                max(0, min(255, 200 + wave))
            )
            surf.set_at((x, y), color)
    return surf

