def show_error_message(message):
    """Show error message dialog"""
    overlay = pygame.Surface((WIDTH, HEIGHT), pygame.SRCALPHA)
    overlay.fill((0, 0, 0, 150))
    window.blit(overlay, (0, 0))
    
    dialog_width = 500
    dialog_height = 150
    dialog_x = (WIDTH - dialog_width) // 2
    dialog_y = (HEIGHT - dialog_height) // 2
    
    pygame.draw.rect(window, (255, 240, 240), (dialog_x, dialog_y, dialog_width, dialog_height))
    pygame.draw.rect(window, (200, 0, 0), (dialog_x, dialog_y, dialog_width, dialog_height), 4)
    
    # Split message if too long
    words = message.split(' ')
    lines = []
    current_line = ""
    
    for word in words:
        test_line = current_line + word + " "
        if font.size(test_line)[0] < dialog_width - 40:
            current_line = test_line
        else:
            lines.append(current_line)
            current_line = word + " "
    
    if current_line:
        lines.append(current_line)
    
    # Draw each line
    for i, line in enumerate(lines):
        line_text = font.render(line, True, (150, 0, 0))
        window.blit(line_text, (dialog_x + 20, dialog_y + 30 + i * 25))
    
    # OK button
    ok_button = pygame.Rect(dialog_x + dialog_width//2 - 40, dialog_y + dialog_height - 50, 80, 30)
    pygame.draw.rect(window, (200, 0, 0), ok_button)
    pygame.draw.rect(window, (150, 0, 0), ok_button, 2)
    
    ok_text = font.render("OK", True, WHITE)
    window.blit(ok_text, (ok_button.x + 40 - ok_text.get_width()//2, 
                         ok_button.y + 15 - ok_text.get_height()//2))
    
    pygame.display.update()
    
    # Wait for OK click
    waiting = True
    while waiting:
        for event in pygame.event.get():
            if event.type == pygame.QUIT:
                pygame.quit()
                quit()
            if event.type == pygame.KEYDOWN:
                if event.key in [pygame.K_RETURN, pygame.K_ESCAPE, pygame.K_SPACE]:
                    waiting = False
            if event.type == pygame.MOUSEBUTTONDOWN:
                if ok_button.collidepoint(event.pos):
                    waiting = False

# === POKéMON CENTER FUNCTIONS ===
def heal_pokemon_team():
    """Fully heal all Pokémon in the player's team (HP, status, and PP)"""
    play_healing_sound()
    update_game_time(10)

    for pokemon in player_team:
        # 1. Restore HP
        pokemon["hp"] = pokemon["max_hp"]
        
        # 2. Clear status effects
        clear_status(pokemon)
        
        # 3. Restore PP for all moves
        if "moves" in pokemon:
            for move in pokemon["moves"]:
                # Check if it's a real move (not "--")
                if isinstance(move, dict) and "name" in move:
                    move_name = move["name"]
                    if move_name != "--" and move_name in pokemon_moves:
                        # Get max PP from the move database
                        move_data = pokemon_moves[move_name]
                        move["pp"] = move_data["max_pp"]
                        move["max_pp"] = move_data["max_pp"]
                # Handle old string format (backward compatibility)
                elif isinstance(move, str) and move != "--" and move in pokemon_moves:
                    # Convert string to dictionary with PP
                    move_data = pokemon_moves[move]
                    pokemon["moves"][pokemon["moves"].index(move)] = {
                        "name": move,
                        "pp": move_data["max_pp"],
                        "max_pp": move_data["max_pp"]
                    }

def show_badges():
    """Display the player's badges"""
    window.fill(MENU_BG)
    pygame.draw.rect(window, MENU_BORDER, (15, 5, WIDTH-30, HEIGHT-30), 4)
    
    title = font.render("=== BADGES ===", True, TITLE_COLOR)
    window.blit(title, (WIDTH//2 - title.get_width()//2, 20))
    
    if not player_badges:
        no_badges = font.render("You haven't earned any badges yet!", True, BLACK)
        window.blit(no_badges, (WIDTH//2 - no_badges.get_width()//2, HEIGHT//2))
    else:
        for i, badge in enumerate(player_badges):
            badge_text = font.render(f"✓ {badge}", True, (0, 100, 0))
            window.blit(badge_text, (WIDTH//2 - badge_text.get_width()//2, 80 + i * 50))
    
    back_text = font.render("Press ESC or B to go back", True, BLACK)
    window.blit(back_text, (WIDTH//2 - back_text.get_width()//2, HEIGHT - 60))
    
    pygame.display.update()
    
    waiting = True
    while waiting:
        for event in pygame.event.get():
            if event.type == pygame.QUIT:
                pygame.quit()
                quit()
            if event.type == pygame.KEYDOWN:
                if event.key == pygame.K_ESCAPE:
                    waiting = False

def show_npc_dialogue(lines, npc_name=""):
    """Show NPC dialogue with multiple lines with proper text wrapping"""
    current_line = 0
    
    while current_line < len(lines):
        # Draw the current screen behind the dialogue
        # For simplicity, let's create a simple dialogue box
        
        # Create a semi-transparent overlay
        overlay = pygame.Surface((WIDTH, HEIGHT), pygame.SRCALPHA)
        overlay.fill((0, 0, 0, 1))  # Semi-transparent black
        
        # Draw dialogue box
        dialogue_box = pygame.Rect(50, HEIGHT - 150, WIDTH - 100, 120)
        pygame.draw.rect(overlay, (255, 255, 255), dialogue_box)
        pygame.draw.rect(overlay, (0, 0, 0), dialogue_box, 3)
        
        window.blit(overlay, (0, 0))
        
        # Draw NPC name if provided
        if npc_name:
            name_text = font.render(npc_name, True, (0, 0, 150))
            window.blit(name_text, (70, HEIGHT - 145))
        
        # Wrap text to fit in dialogue box
        text = lines[current_line]
        words = text.split(' ')
        wrapped_lines = []
        current_wrapped_line = ""
        
        # Maximum width for text (dialogue box width minus padding)
        max_text_width = WIDTH - 140  # 70px left padding + 70px right padding
        
        for word in words:
            # Test if adding this word would exceed the width
            test_line = current_wrapped_line + word + " "
            if font.size(test_line)[0] <= max_text_width:
                current_wrapped_line = test_line
            else:
                # Start a new line
                wrapped_lines.append(current_wrapped_line)
                current_wrapped_line = word + " "
        
        # Add the last line
        if current_wrapped_line:
            wrapped_lines.append(current_wrapped_line)
        
        # Draw wrapped text
        for i, line in enumerate(wrapped_lines):
            if i > 2:  # Max 3 lines in the dialogue box
                break
            text_surface = font.render(line, True, (0, 0, 0))
            window.blit(text_surface, (70, HEIGHT - 110 + i * 30))
        
        # Draw continue prompt
        if current_line < len(lines) - 1:
            prompt = font.render("Press ENTER to continue...", True, (0, 5, 0))
        else:
            prompt = font.render("Press ENTER to finish...", True, (1, 5, 0))
        window.blit(prompt, (WIDTH - 380, HEIGHT - 57))
        
        pygame.display.update()
        
        # Wait for input
        waiting = True
        while waiting:
            for event in pygame.event.get():
                if event.type == pygame.QUIT:
                    pygame.quit()
                    quit()
                if event.type == pygame.KEYDOWN:
                    if event.key == pygame.K_RETURN or event.key == pygame.K_SPACE:
                        waiting = False
                        current_line += 1
                    elif event.key == pygame.K_ESCAPE:
                        return  # Exit dialogue early
            pygame.time.delay(10)

def find_tile_pos(map_name, tile_code):
    """Return the (row, col) of the first tile matching tile_code in the given map, or (None, None)."""
    for r, row in enumerate(maps.get(map_name, [])):
        for c, t in enumerate(row):
            if t == tile_code:
                return r, c
    return None, None


def interact_pokemon_center():
    """Handle Pokémon Center interaction"""
    global game_state
    
    # Nurse greeting
    greeting_lines = [
        "Welcome to the Pokémon Center!",
        "We restore your tired Pokémon to full health.",
        "Would you like to heal your Pokémon?"
    ]
    
    show_npc_dialogue(greeting_lines, "Nurse Joy")
    
    # Ask if player wants to heal
    healing = True
    while healing:
        # Clear the area where the prompt will be
        window.fill(WHITE)
        
        # Draw a simple menu
        pygame.draw.rect(window, (240, 240, 240), (50, HEIGHT - 150, WIDTH - 100, 120))
        pygame.draw.rect(window, BLACK, (50, HEIGHT - 150, WIDTH - 100, 120), 3)
        
        question = font.render("Heal your Pokémon?", True, BLACK)
        option1 = font.render("1. Yes (Press 1 or Y)", True, BLACK)
        option2 = font.render("2. No (Press ESC)", True, BLACK)
        
        window.blit(question, (WIDTH//2 - question.get_width()//2, HEIGHT - 130))
        window.blit(option1, (WIDTH//2 - option1.get_width()//2, HEIGHT - 100))
        window.blit(option2, (WIDTH//2 - option2.get_width()//2, HEIGHT - 70))
        
        pygame.display.update()
        
        # Wait for input
        waiting_for_choice = True
        while waiting_for_choice:
            for event in pygame.event.get():
                if event.type == pygame.QUIT:
                    pygame.quit()
                    quit()
                if event.type == pygame.KEYDOWN:
                    if event.key in [pygame.K_1, pygame.K_y, pygame.K_RETURN, pygame.K_SPACE, pygame.K_RETURN, pygame.K_z]:
                        # Heal Pokémon
                        play_healing_sound()  # ADD THIS LINE
                        heal_pokemon_team()
                        
                        # Show healing animation/sequence
                        healing_lines = [
                            "Okay, I'll take your Pokémon for a moment.",
                            "...",
                            "Thank you for waiting!",
                            "Your Pokémon are fully healed!",
                            "We hope to see you again!"
                        ]
                        show_npc_dialogue(healing_lines, "Nurse Joy")
                        
                        waiting_for_choice = False
                        healing = False
                    elif event.key in [pygame.K_2, pygame.K_n, pygame.K_ESCAPE, pygame.K_BACKSPACE, pygame.K_x]:
                        # Don't heal
                        show_npc_dialogue(["Okay, come back anytime!"], "Nurse Joy")
                        waiting_for_choice = False
                        healing = False
            pygame.time.delay(10)

