sound_effects = {}

# Load the simple sounds
def load_simple_sounds():
    """Load sound effects from files in music folder"""
    global sound_effects
    
    # Clear existing sounds
    sound_effects = {}
    
    # Dictionary of all sound files
    sound_files = {
        "menu_select": "soundeffect.mp3",
        "menu_confirm": "soundeffect.mp3",
        "pokemon_heal": "pokemonheal.mp3",
        "level_up": "level_up.mp3",
        "error": "soundeffect.mp3",
    }
    
    for sound_name, filename in sound_files.items():
        try:
            # Get the path to the music folder
            base_folder = os.path.dirname(os.path.abspath(__file__))
            sound_path = os.path.join(base_folder, "music", filename)
            
            if os.path.exists(sound_path):
                sound = pygame.mixer.Sound(sound_path)
                sound_effects[sound_name] = sound
            else:
                print(f"✗ File not found: {sound_path}")
                
        except Exception as e:
            print(f"✗ Could not load {filename}: {e}")

def play_sound(sound_name, volume=0.7):
    """Play a sound effect"""
    if sound_name in sound_effects:
        sound = sound_effects[sound_name]
        sound.set_volume(volume * MASTER_VOLUME)
        sound.play()
    else:
        print(f"Sound effect '{sound_name}' not found!")

def play_menu_select():
    """Play menu selection sound"""
    play_sound("menu_select", 0.6)

