# === SPRITE LOADING ===
def load_sprite(name, size=TILE_SIZE):
    """Load sprite with multiple fallback locations"""
    base_folder = os.path.dirname(os.path.abspath(__file__))
    
    # Define all possible locations where sprites might be
    possible_paths = [
        os.path.join(base_folder, name + ".png"),  # Directly in main folder
        os.path.join(base_folder, "assets", name + ".png"),
        os.path.join(base_folder, "trainer_sprites", name + ".png"),
        os.path.join(base_folder, "back_sprites", name + ".png"),
        os.path.join(base_folder, "front_sprites", name + ".png"),
        os.path.join(base_folder, "sprites", name + ".png"),
        os.path.join(base_folder, "images", name + ".png"),
        os.path.join(base_folder, "textures", name + ".png"),
    ]
    
    for possible_path in possible_paths:
        for path in sprite_path_candidates(possible_path):
            if not os.path.exists(path):
                continue
            try:
                return load_sprite_image(path, size=(size, size))
            except Exception as e:
                print(f"DEBUG: Error loading {path}: {e}")
    
    # Fallback: create colored sprite based on sprite type
    surf = pygame.Surface((size, size), pygame.SRCALPHA)
    
    # Different colors for different sprite types
    if "player" in name.lower() or "trainer" in name.lower():
        surf.fill((0, 0, 255, 255))  # Blue for trainers
    elif "back" in name.lower():
        surf.fill((0, 255, 0, 255))  # Green for back sprites
    elif "front" in name.lower():
        surf.fill((255, 255, 0, 255))  # Yellow for front sprites
    elif "grass" in name.lower() or "tree" in name.lower() or "wall" in name.lower():
        surf.fill((100, 200, 100, 255))  # Green for environment
    else:
        surf.fill((255, 0, 0, 255))  # Red for missing sprites
    
    # Add a black border
    pygame.draw.rect(surf, (0, 0, 0), (0, 0, size, size), 2)
    
    # Add text showing sprite name (if size is large enough)
    if size > 16:
        try:
            font = pygame.font.Font(None, max(8, size // 4))
            text = font.render(name[:3], True, (255, 255, 255))
            text_rect = text.get_rect(center=(size//2, size//2))
            surf.blit(text, text_rect)
        except:
            pass
    
    return surf

def load_sprite_from_folder(folder_name, sprite_name, size=TILE_SIZE):
    """Load sprite from a specific folder with detailed debugging"""
    base_folder = os.path.dirname(os.path.abspath(__file__))
    path = find_sprite_path(os.path.join(base_folder, folder_name, sprite_name + ".png"))
    
    # Check if the folder exists
    folder_path = os.path.join(base_folder, folder_name)
    if not os.path.exists(folder_path):
        return create_fallback_sprite(sprite_name, size)
    
    # Check if the file exists
    if not os.path.exists(path):
        print(f"DEBUG ERROR: File '{sprite_name}.png' not found at {path}")
        
        # List what files ARE in the folder
        try:
            files = os.listdir(folder_path)
            
            # Check for case-insensitive matches
            for file in files:
                if file.lower() in (sprite_name.lower() + ".png", sprite_name.lower() + ".gif"):
                    # Use the correct case
                    path = os.path.join(base_folder, folder_name, file)
        except Exception as e:
            print(f"DEBUG: Error listing folder: {e}")
        
        return create_fallback_sprite(sprite_name, size)
    
    # Try to load the file
    try:
        sprite = load_sprite_image(path, size=(size, size))
        print(f"DEBUG: Successfully loaded '{sprite_name}.png'")
        return sprite
    except Exception as e:
        print(f"DEBUG ERROR: Failed to load '{sprite_name}.png': {e}")
        return create_fallback_sprite(sprite_name, size)

def create_fallback_sprite(sprite_name, size):
    """Create a colored fallback sprite with debug info"""
    surf = pygame.Surface((size, size), pygame.SRCALPHA)
    
    # Different colors for debugging
    if "player" in sprite_name.lower():
        color = (0, 0, 255, 255)  # Blue
        label = "PLAYER"
    elif "rival" in sprite_name.lower():
        color = (255, 0, 0, 255)  # Red
        label = "RIVAL"
    elif "girl" in sprite_name.lower():
        color = (255, 0, 255, 255)  # Purple
        label = "GIRL"
    elif "grass" in sprite_name.lower():
        color = (100, 200, 100, 255)  # Green
        label = "GRASS"
    elif "tree" in sprite_name.lower():
        color = (34, 139, 34, 255)  # Forest green
        label = "TREE"
    elif "wall" in sprite_name.lower():
        color = (139, 69, 19, 255)  # Brown
        label = "WALL"
    else:
        color = (255, 165, 0, 255)  # Orange
        label = sprite_name[:3].upper()
    
    surf.fill(color)
    
    # Add border
    pygame.draw.rect(surf, (0, 0, 0), (0, 0, size, size), 2)
    
    # Add label
    if size > 20:
        try:
            font = pygame.font.Font(None, max(10, size // 3))
            text = font.render(label, True, (255, 255, 255))
            text_rect = text.get_rect(center=(size//2, size//2))
            surf.blit(text, text_rect)
        except:
            pass
    
    return surf

