def get_pokemon_sprite_form_suffix(name):
    """Return the regional form suffix for a Pokémon name, if any."""
    if name is None:
        return ""

    normalized = name.strip().replace("_", " ").replace("-", " ")
    lowered = normalized.lower()

    if "hisuian" in lowered or "hisui" in lowered or normalized.startswith("H "):
        return "hisui"
    if "alolan" in lowered or "alola" in lowered or normalized.startswith("A "):
        return "alola"
    if "galarian" in lowered or "galar" in lowered or normalized.startswith("G "):
        return "galar"
    if "paldean" in lowered or "paldea" in lowered or normalized.startswith("P "):
        return "paldea"

    if normalized.startswith("H-") or normalized.startswith("Hisuian ") or normalized.startswith("Hisui "):
        return "hisui"
    if normalized.startswith("A-") or normalized.startswith("Alolan ") or normalized.startswith("Alola "):
        return "alola"
    if normalized.startswith("G-") or normalized.startswith("Galarian ") or normalized.startswith("Galar "):
        return "galar"
    if normalized.startswith("P-") or normalized.startswith("Paldean ") or normalized.startswith("Paldea "):
        return "paldea"
    return ""


def load_pokemon_sprite(name, is_player=False, size_multiplier=1.0):
    """Load a National Dex-numbered Pokémon sprite in the requested orientation."""
    dex_num = get_national_dex_number(name)
    form_suffix = get_pokemon_sprite_form_suffix(name)
    sprite_files = []

    def add_numbered_candidates(front_or_back, include_form):
        if 1 <= dex_num <= 1025:
            if include_form and form_suffix:
                sprite_files.append(front_or_back(f"{dex_num:04d}-{form_suffix}.png"))
                sprite_files.append(front_or_back(f"{dex_num:04d}{'a' if front_or_back is get_back_sprite_path else ''}-{form_suffix}.png"))
            sprite_files.append(front_or_back(f"{dex_num:04d}.png" if front_or_back is get_front_sprite_path else f"{dex_num:04d}a.png"))

    if is_player:
        add_numbered_candidates(get_back_sprite_path, True)
        sprite_files.extend([
            get_back_sprite_path(f"{name.lower()}sprite.png"),
            get_back_sprite_path(f"{name}_back.png"),
            os.path.join(game_folder, f"{name}sprite.png"),
            os.path.join(game_folder, f"{name}_back.png"),
        ])
        add_numbered_candidates(get_front_sprite_path, True)
        sprite_files.extend([
            get_front_sprite_path(f"{name}.png"),
            get_front_sprite_path(f"{name}_front.png"),
            os.path.join(game_folder, f"{name}.png"),
            os.path.join(game_folder, f"{name}_front.png"),
        ])
    else:
        add_numbered_candidates(get_front_sprite_path, True)
        sprite_files.extend([
            get_front_sprite_path(f"{name}.png"),
            get_front_sprite_path(f"{name}_front.png"),
            os.path.join(game_folder, f"{name}.png"),
            os.path.join(game_folder, f"{name}_front.png"),
        ])
        add_numbered_candidates(get_back_sprite_path, True)
        sprite_files.extend([
            get_back_sprite_path(f"{name.lower()}sprite.png"),
            get_back_sprite_path(f"{name}_back.png"),
            os.path.join(game_folder, f"{name}sprite.png"),
            os.path.join(game_folder, f"{name}_back.png"),
        ])

    seen_paths = set()
    for sprite_file in sprite_files:
        for path in sprite_path_candidates(sprite_file):
            if not path or path in seen_paths:
                continue
            seen_paths.add(path)
            if not os.path.exists(path):
                continue
            try:
                base_size = pokemon_sizes.get(name, (SPRITE_SIZE, SPRITE_SIZE))
                target_size = tuple(max(1, int(dimension * size_multiplier)) for dimension in base_size)
                return load_sprite_image(path, fit_size=target_size)
            except Exception as e:
                print(f"Error loading sprite {path}: {e}")
    
    # Fallback: create colored placeholder
    base_size = pokemon_sizes.get(name, (SPRITE_SIZE, SPRITE_SIZE))
    target_size = tuple(max(1, int(dimension * size_multiplier)) for dimension in base_size)
    surf = pygame.Surface(target_size, pygame.SRCALPHA)
    
    # Different colors for player vs opponent
    if is_player:
        surf.fill((200, 255, 200, 255))  # Light green for player
    else:
        surf.fill((255, 200, 200, 255))  # Light red for opponent
    
    name_text = font_small.render(name, True, (0, 0, 0))
    text_rect = name_text.get_rect(center=(target_size[0]//2, target_size[1]//2))
    surf.blit(name_text, text_rect)
    
    pygame.draw.rect(surf, (100, 0, 0), (0, 0, target_size[0], target_size[1]), 2)
    
    return surf

