def interact_with_npc(npc_id):
    """Handle interaction with an NPC"""
    if npc_id in npcs:
        npc = npcs[npc_id]
        dialogues = npc.get("dialogues", [])
        show_npc_dialogue(dialogues, npc["name"])
        
        if npc_id == "prof_gale":
            # Professor Gale's dialogue after starter selection
            if starter_selected:
                gale_dialogues = [
                    "Professor Gale: How's your Pokémon doing?",
                    "Professor Gale: Remember, the road to becoming a Pokémon Master is long!",
                    "Professor Gale: Anyways, good luck on your journey!"
                ]
                show_npc_dialogue(gale_dialogues)
            else:
                # Show starter selection if not done yet
                show_gale_introduction_complete()

def check_npc_interaction():
    """Check if player is facing an NPC and can interact"""
    # Calculate tile in front of player based on direction
    front_row, front_col = player_row, player_col
    
    # Determine which way player is facing based on last movement
    if player_img in [player_left, player_walk_left, player_run_left]:
        front_col -= 1
    elif player_img in [player_right, player_walk_right, player_run_right]:
        front_col += 1
    elif player_img in [player_up, player_walk_up, player_run_up]:
        front_row -= 1
    elif player_img in [player_down, player_walk_down, player_run_down]:
        front_row += 1
    
    if current_map in npc_positions:
        for npc_pos in npc_positions[current_map]:
            n_row, n_col, npc_id = npc_pos
            if (front_row, front_col) == (n_row, n_col):
                # Show interaction hint
                hint_text = font_small.render("Press E to talk", True, WHITE)
                pygame.draw.rect(window, (0, 0, 0, 128), 
                            (player_x, player_y - 30, 120, 25))
                window.blit(hint_text, (player_x + 10, player_y - 25))
                break

def check_trainer_at_position(map_name, row, col):
    """Check if there's a trainer at the specified position"""
    if map_name in trainer_positions:
        for trainer_row, trainer_col, trainer_id in trainer_positions[map_name]:
            if trainer_row == row and trainer_col == col:
                # Check if trainer has been defeated
                if not trainer_defeated.get(trainer_id, False):
                    return trainer_id
    return None

